local KT={}--6.0 (11-03): constant / data tables packed here (Lua 5.2 allows 200 locals in the main chunk; tool: lua_locals.py pack)
-- ko 5.0: 성내 거리 (addon "town"). The DOS original: 유비 leaves the 회의장 by a floor arrow, walks the town street, steps into
-- the 주점 … where townsfolk talk (IPPAN0M.R3), and leaves the town onto the region map (MMAP.R3), where he walks the roads to
-- the other towns of the chapter. Here, during a free city phase of a town that has data:
--  · story scene: a floor arrow where the scene's way out is (STORY, by scene picture); click it and 유비 walks there
--  · street (a 성영걸전 background, arrows painted on it): click a person and 유비 walks up to him and they talk (nobody walks
--    by clicking the floor); click a door sign and he walks to the door, "OO\129\102 \131\082\130\083\129\094\134\121\129\075\129\076\129\089?"; 회의장 = back to the story
--    scene (only in the town the story is in), 마을 밖 = the region map
--  · rooms: the way out is painted on the floor at the room's door
--  · region map (the DOS map, its 16 colours fitted to screenshots, 20px tiles = the DOS 512x320 view at 640x400): click a town
--    and 유비 walks the roads to it (the DOS road bitmap, one bit per 2x2 tiles); a town he cannot go to yet, a battlefield or a
--    pass answers "\131\091\135\069\131\109\139\109 \129\071\130\108\129\088 \129\113 \130\097\129\075\129\076\129\077.". Towns open as the chapter's story reaches them (free: the first free phase there).
-- JY.SubScene / JY.Smap / 现在地 of the story scene are put back on return.
-- Walking in scenes follows the iso axes (CC.DX/CC.DY: dir 0 up-right, 1 down-left, 2 up-left, 3 down-right).
-- smap: 116 마을 거리(평원 모델), 117 주점, 119~122 화살표 ul ur dl dr, 125 시골 마을(성영걸전 208), 131 궁궐 앞(큰 마을),
-- 133 1장 지역 지도 (1920x1920), 134 2장 지역 지도 (1440x2240). 118 123 124 126~130 132 are empty (pictures tried and dropped).
-- Build (game folder): perl "../\129\126\130\064\130\066\130\068\130\069 \130\071\130\072\130\070 5.0 \134\075\129\095\132\111/\134\075\129\095\132\111/\129\068\130\119/free_hz.pl" < "../\129\126\130\064\130\066\130\068\130\069 \130\071\130\072\130\070 5.0 \134\075\129\095\132\111/\134\075\129\095\132\111/addon/town_src.lua" > script/addon/town.lua
local LOC="\207\214\212\218\181\216"-- 现在地
local CHAP="\213\194\189\218\195\251"-- 章节名
local NAME="\208\213\195\251"-- 姓名
local FIG="\208\206\207\243"-- 形象 (city figure)
-- 10-10: the figure a person is really drawn with (unique addon: listed persons have their own city figure KO_CITY_BASE+pid), so
--  townsfolk who share a stored figure but have their own sprites (산적 311~313) can stand side by side
local function koTownFig(id) local f=rawget(_G,"koWujeIdentity") local src=(f and f(id)) or id local u=rawget(_G,"koUniqueCity") local ps=rawget(_G,"koGenPrivSlot") local pv=ps and ps(id) if pv and u and u[pv] then return (rawget(_G,"KO_CITY_BASE") or 300)+pv end if u and u[src] and (not CONFIG.koCamp or string.find(CC.koGenEdit or "",",c"..src..",",1,true)) then return (rawget(_G,"KO_CITY_BASE") or 300)+src end local cf=rawget(_G,"koWujeCityFigure") local fig=cf and cf(id) if fig then return fig end if u and u[src] then return (rawget(_G,"KO_CITY_BASE") or 300)+src end return JY.Person[id][FIG] end
KT.ARROW={ul=119,ur=120,dl=121,dr=122}
KT.ADIR={ul=2,ur=0,dl=1,dr=3}-- the walking dir each arrow points to
KT.OPP={[0]=1,0,3,2}
-- 걷는 사람: 유비, 삼형제 외전 중(view 애드온)이면 그 형제
local function ME()
local f=rawget(_G,"koViewSide")
if f and f() then local b=koViewBro() if b>0 then return b end end
return 1
end

