-- the town model (평원's street, smap 116): every town that is a small castle on the region map uses it — 회의장 arrow top-left,
-- 마을 밖 bottom-left, the 주점 door by the stall, four townsfolk where the picture has room. people/inn: {type,line} x4
KT.SPOT={{14,11,1},{25,14,1},{24,18,2},{7,15,2}}
local function small(people,inn)
local p={}
for i,r in ipairs(people) do local s=KT.SPOT[i] p[i]={r[1],s[1],s[2],s[3],r[2]} end
local doors={
{to="story",label="\130\125\131\080\131\097",x=8,y=4,arrow="ul"},
{to="out",label="\133\088\129\083 \139\119",x=3,y=19,arrow="dl"},
}
if inn then doors[3]={to="inn",label="\130\075\135\070",x=23,y=5} end-- a town without a 주점 in the original has no sign
return {street={bg=116,doors=doors,people=p},inn=inn}
end
-- the village model (a hut on the region map, smap 125 = 성영걸전 208, arrows painted top-left and bottom-left): no buildings,
-- the top-left path leads to the story house (home: its label)
KT.VSPOT={{12,10,1},{20,9,1},{17,13,2},{25,11,2}}
local function village(people,home)
local p={}
for i,r in ipairs(people) do local s=KT.VSPOT[i] p[i]={r[1],s[1],s[2],s[3],r[2]} end
return {street={bg=125,doors={
{to="story",label=home,x=6.5,y=6.5,arrow="ul"},
{to="out",label="\133\088\129\083 \139\119",x=6,y=20,arrow="dl"},
},people=p}}
end
-- the big-town model (a big castle on the region map): the same street, but its top-left arrow leads to the 궁궐 앞 screen
local function big(people,inn,palace)
local t=small(people,inn)
t.street.doors[1]={to="palace",label="\134\088\142\066",x=8,y=4,arrow="ul"}
t.palace=palace
return t
end
