-- the line of that time for slot i of place key ("street"/"inn"/"palace") of town in chapter c now, or nil (the chapter's own)
local function revisitLine(c,town,key,i)
local best,ba=nil,-1
local function try(r)
if r and JY.EventID>r.after and r.after>ba and r[key] and r[key][i] then best,ba=r[key][i],r.after end
end
local r=KT.REVISIT[c.key]
try(r and r[town])
for _,st in ipairs((KT.STAGE[c.key] or {})[town] or {}) do try(st) end
return best
end
local T=nil-- the open town: {chap,home,town,mode,cur,lines,nick,door,R}
function koTidNick(pid) return T and T.nick and pid and T.nick[pid] or nil end-- 10-10: the status line under the scene shows a townsman by his nickname (patch_상태줄별명)
