local I_NAME,I_DESC,I_PRICE="\195\251\179\198","\203\181\195\247","\188\219\214\181"-- 名称 说明 价值
local P_LORD,P_NAME,P_ITEM8="\190\253\214\247","\208\213\195\251","\181\192\190\223\056"-- 君主 姓名 道具8
KT.SHOPKEY="\129\068\130\119\129\067"-- JY.Base field read by Shop()
KT.SHOPKEEPER=375
local INNKEEPER,DRINKER=358,359-- 상인 / 나그네 records, shown as 주점 주인 / 술꾼
-- the shop of a town (0 = none); the story town keeps the number the story set
local function townShop(name)
if name==T.home then return JY.Base[KT.SHOPKEY] or 0 end
local s=T.chap.shop and T.chap.shop[name]
if type(s)=="table" then local n=0 for _,r in ipairs(s) do if r[1]<=JY.EventID then n=r[2] end end return n end
return s or 0
end
-- Shop() always opens with the 도구상's "\133\102\130\098 \129\067\129\106\129\104\129\076\129\077." and, from shop 2 on, a menu of every shop so far (진류 북평 …);
-- skip = opened by talking to this town's 도구상: that line is left out and the menu answers with this town's shop by itself
-- the 특산품 list of a town in the open chapter, or nil
-- the 특산품 상인 sells through the base addon's koShopBuy: with base off there is no merchant (the townsman keeps his line)
local HAS_SHOP=rawget(_G,"koShopBuy")~=nil
function koSpecialTable()--6.0 (11-03): a story has its own special-merchant table (script/camp/<id>/special_camp.lua), keyed by story phase
if CONFIG.koCamp and type(rawget(_G,"koCampSpecial"))=="table" then return koCampSpecial,koCampSpecialKeys end
return KT.SPECIAL,nil
end
function koSpecialPhase()--6.0 (11-03): the story phase now (1~4, 9 = not in a game), nil in the base story
local st=rawget(_G,"koCampSpecialStart")
if not (CONFIG.koCamp and type(st)=="table") then return nil end
if JY.Base==nil or JY.Status==GAME_START then return 9 end
local n=1 for k,v in ipairs(st) do if (JY.EventID or 0)>=v then n=k end end
return n
end
local function townSpecial(name)
if not HAS_SHOP then return nil end
local SPT,SPK=koSpecialTable()
local s
if SPK then s=SPT[SPK[koSpecialPhase() or 0] or ""] else s=SPT[T.chap.key] end
s=s and s[name]
if s then return koPromotionStock(s) end
end
local function townTalent()
if rawget(_G,"koWujeCampaignActive") and koWujeCampaignActive() then return nil end
local t=KT.TALENT[T.chap.key] t=t and t[T.town]
if t==nil or JY.EventID<KT.TALENT_EV[1] or JY.EventID>KT.TALENT_EV[2] then return nil end
for _,id in ipairs(t) do if JY.Person[id][P_LORD]~=1 then return id end end
end

-- 마을 견문록: every townsman's line (street, 주점, 궁궐 앞; the 도구상's own line where he stands) once heard is kept, like
-- the 업적, machine-wide in ko_settings (CC.koTownHeard: "1"/"0" by BOOK index). The 기록 screen gets a tab listing them by
-- chapter and town (the region map's place order), and hearing them all is 업적 21.

-- Campaign town contents use the original town engine and journal registration.
do local KC=rawget(_G,"koCamp") if KC and KC.townCities then--ko 6.0 campaigns: only when a campaign runs
local WUALIAS=KC.townAlias or {["\129\103\130\071"]="\129\103\129\093",["\134\110\131\123"]="\134\110",["\131\071\130\075"]="\134\110",["\135\109\129\068"]="\135\109\134\103",["\134\108\131\123"]="\134\108",["\129\079\131\123"]="\129\109\129\079",["\133\103\130\084"]="\130\073\142\083"}
local WUCITIES=KC.townCities
for _,c in pairs(DATA) do
 c.towns={} c.shop={} c.region.open={}
 for _,p in ipairs(c.region.places) do
  p[1]=WUALIAS[p[1]] or p[1]
  if p[4]>=3 or WUCITIES[p[1]] then
   p[4]=3
   c.towns[p[1]]=small({{"M","\134\114\129\083 \139\088\131\118\131\071 \130\066\129\102 \130\084\129\113\131\066\129\083 \131\101\130\080\129\097\135\073\130\086\129\091."},{"S","\132\115\129\090\129\111 \131\065\129\119\129\083 \134\106\141\097\131\115\135\073\130\086\129\091."},{"T","\134\069\135\070 \130\125\131\080\131\097\131\109\132\083 \137\066\129\110\129\094\129\065 \133\098\130\066 \131\101\130\080\130\104 \132\084\133\123\129\088 \129\113 \132\079\129\075\129\076\129\077."},{"F","\130\066\130\100\129\071 \139\091\131\118 \129\097\131\094\142\087\129\117 \131\119\134\091\129\066\131\070\131\109\129\065 \138\111\134\121\129\075\129\076\129\077."}},{{"T","\133\088\129\083\129\083 \129\091\129\094\134\066 \135\100\130\086 \139\093\130\083 \129\094\131\100 \132\079\129\075\129\076\129\077."},{"M","\131\097\129\113\131\082\129\123 \129\071\133\069\131\071\130\104 \131\118\134\117\131\096\129\065 \130\075\135\070 \130\075\129\106\129\083 \139\113\129\110\131\115\135\073\130\086\129\091."}})
   c.shop[p[1]]=1
  end
 end
end
end end

KT.WHERE={street="\134\069\129\117",inn="\130\075\135\070",palace="\134\088\142\066"}
local BOOK,BOOKIDX={},{}
for _,ck in ipairs({"\129\1001\131\097","\129\1002\131\097","\129\1003\131\097","\129\1004\131\097"}) do
local C=DATA[ck]
BOOKIDX[ck]={}
local names={}
for _,p in ipairs(C.region.places) do names[#names+1]=p[1] end
local rest={}
for nm,_ in pairs(C.towns) do rest[#rest+1]=nm end
table.sort(rest)
for _,nm in ipairs(rest) do names[#names+1]=nm end-- (a town not on the place list, if any, after them)
for _,nm in ipairs(names) do
local td=C.towns[nm]
if td and not BOOKIDX[ck][nm] then
local ix={}
BOOKIDX[ck][nm]=ix
local function add(key,i,line) BOOK[#BOOK+1]={chap=ck,town=nm,where=KT.WHERE[key],line=line} ix[key..i]=#BOOK end
local sp=HAS_SHOP and KT.SPECIAL[ck] and KT.SPECIAL[ck][nm]
for i,r in ipairs(td.street.people) do
local line=r[5]
if sp and i==2 then local sl=KT.SHOPLINE[ck] line=sl and sl[nm] or "\130\083\131\087 \129\091\135\073\130\086\129\091." end
add("street",i,line)
end
for _,key in ipairs({"inn","palace"}) do
for i,r in ipairs(td[key] or {}) do if i<=#KT.ROOM[key].spots then add(key,i,r[2]) end end
end
end
end
end
local function heardStr() return CC.koTownHeard or "" end
local function isHeard(b) return string.sub(heardStr(),b,b)=="1" end
local function heardCount()
local n=0
for b=1,#BOOK do if isHeard(b) then n=n+1 end end
return n
end
local function hear(b)
if b==nil or isHeard(b) then return end
local s=heardStr()
if #s<b then s=s..string.rep("0",b-#s) end
CC.koTownHeard=string.sub(s,1,b-1).."1"..string.sub(s,b+1)
koSave()
if heardCount()>=#BOOK and rawget(_G,"koAchCheck") then koAchCheck(true) end
end
koAddon.saveKeys[#koAddon.saveKeys+1]={key="koTownHeard",default=""}
if rawget(_G,"koAchList") then
koAchList[#koAchList+1]={21,"\133\088\129\083 \134\084\133\090\133\108","\133\088\129\083 \130\114\134\118\131\082\131\080 \129\071\133\069\131\071\130\104 \130\090\130\091 \138\094\130\098\129\077",function() return heardCount(),#BOOK end}
end
-- a line cut to rows of at most w bytes (hz: 2 bytes a letter, 8px a byte at size 16), at a space where it can
local function wrap(s,w)
local out={}
local i,n=1,#s
while i<=n do
if n-i+1<=w then out[#out+1]=string.sub(s,i) break end
local j,sp=i,nil
while j<=n do
local c=string.byte(s,j)
local l=(c>=128) and 2 or 1
if j+l-i>w then break end
if c==32 then sp=j end
j=j+l
end
local cut=(sp and sp>i) and sp or j
out[#out+1]=string.sub(s,i,cut-1)
i=cut
while i<=n and string.byte(s,i)==32 do i=i+1 end
end
return out
end
if rawget(_G,"koRecTabs") then
local ROWS,LH,WB=13,25,80
-- one page a town (a town too long for one page goes on; a line not heard yet is a single "\161\173\161\173" row)
local function pages()
local P={}
local i=1
while i<=#BOOK do
local b=BOOK[i]
local j=i
while j<=#BOOK and BOOK[j].chap==b.chap and BOOK[j].town==b.town do j=j+1 end
local pg={chap=b.chap,town=b.town,from=i,to=j-1,rows={}}
for k=i,j-1 do
local ls=isHeard(k) and wrap(BOOK[k].line,WB) or {"\161\173\161\173"}
if #pg.rows>0 and #pg.rows+#ls>ROWS then P[#P+1]=pg pg={chap=b.chap,town=b.town,from=i,to=j-1,rows={},cont=true} end
for m,l in ipairs(ls) do pg.rows[#pg.rows+1]={k=k,first=(m==1),txt=l} end
end
P[#P+1]=pg
i=j
end
return P
end
koRecTabs[#koRecTabs+1]={label="\134\084\133\090\133\108",per=1,
n=function() return #pages() end,
draw=function(page,c)
local P=pages()
local pg=P[page]
if not pg then return end
local got=0
for k=pg.from,pg.to do if isHeard(k) then got=got+1 end end
c.txt(c.ox+24,c.oy+60,pg.chap.."  "..pg.town..(pg.cont and " (\129\071\130\083\131\087)" or "").."    "..got.." / "..(pg.to-pg.from+1),C_Name)
c.rtext(c.ox+744,c.oy+60,"\130\066\133\114 "..heardCount().." / "..#BOOK,M_Gray)
-- Pagination is drawn by the record screen footer.
local x=c.ox+24
for r,w in ipairs(pg.rows) do
local y=c.oy+90+(r-1)*LH
local heard=isHeard(w.k)
if w.first then
if r>1 then lib.DrawRect(x,y-5,x+720,y-5,RGB(86,68,43)) end
c.txt(x,y,"["..BOOK[w.k].where.."]",heard and C_Name or M_Gray)
end
c.txt(x+64,y,w.txt,heard and M_White or M_Gray)
end
if got==0 then c.ctext(c.oy+90+ROWS*LH-LH,"\131\123\131\095 \134\069\129\117\129\102\131\087 \129\071 \133\088\129\083 \130\114\134\118\131\082\129\102\129\081 \136\124\129\083 \130\064\130\083 \131\115\131\111\129\090.",M_Gray) end
end}
end
-- the 특산품 상인's own little shop (the 도구 구입 steps of Shop(): item, its description and price, who takes it, koShopBuy)
local function townSpecialPrice(iid)
local price=JY.Item[iid][I_PRICE]
if koIsPromotionItem(iid) then return price end
return math.ceil(price*KT.SPECIAL_RATE)
end
local function townSpecialShop(list)
local personmenu,personnum={},0
for i=1,JY.PersonNum-1 do
if JY.Person[i][P_LORD]==1 then personmenu[i]={fillblank(JY.Person[i][P_NAME],11),nil,1} personnum=personnum+1
else personmenu[i]={"",nil,0} end
end
local function box()
JY.Tid=KT.SHOPKEEPER
DrawSMap()
DrawYJZBox(32,32,"\129\120\132\091\131\066",M_White,true)
end
while true do
box()
talk_sub(KT.SHOPKEEPER,"\129\071\135\069\129\102\131\087\132\086 \134\086\130\098 \131\065\129\119\129\104\129\076\129\077. \129\073\135\074\129\083 \130\114\130\086\134\121\129\075\129\076\129\089?")
local menu={}
for i,iid in ipairs(list) do menu[i]={fillblank(JY.Item[iid][I_NAME],13),nil,1} end
local r=ShowMenu(menu,#menu,0,0,156,0,0,3,1,16,M_White,M_White)
if r<=0 then PlayWavE(1) break end
local iid=list[r]
local p10=townSpecialPrice(iid)
local shownPrice=koIsPromotionItem(iid) and koShopP(iid) or p10
local x,y=145,CC.ScreenH/2
lib.PicLoadCache(4,50*2,x,y,1)
DrawString(x+16,y+16,JY.Item[iid][I_NAME],C_Name,16)
DrawStr(x+16,y+36,GenTalkString(JY.Item[iid][I_DESC],18),M_White,16)
