local function townShopOpen(sid,skip)
local old,otalk,omenu=JY.Base[KT.SHOPKEY],talk,ShowMenu
JY.Base[KT.SHOPKEY]=sid
if skip then
local first=true
local head=fillblank("\129\103\129\093",11)
talk=function(id,...) if first and id==KT.SHOPKEEPER then first=false return end return otalk(id,...) end
ShowMenu=function(m,...) if type(m)=="table" and m[1] and m[1][1]==head and #m==sid then return sid end return omenu(m,...) end
end
local ok,err=pcall(Shop)
JY.Base[KT.SHOPKEY],talk,ShowMenu=old,otalk,omenu
if not ok then error(err,0) end
end

-- the chapter block and the town of the current free city phase
local function chapter()
local f=rawget(_G,"koWujeNativeTownContext") if f then local c=f() if c then return c end end
local ch=JY.Base[CHAP] or ""
for k,v in pairs(DATA) do
if string.sub(ch,1,#k)==k then return v end
end
end
function koTownData()
local c=chapter()
local loc=JY.Base[LOC] or ""
local f=rawget(_G,"koWujeNativeTownContext") if f then local wc,home=f() if wc and not T then loc=home end end
if c and c.towns[loc] then return c.towns[loc],loc,c end
return nil
end
local function avail()
return JY.Status==GAME_SMAP_MANUAL and koTownData()~=nil
end

