end
local koStoryInn,koStoryHomeOf=nil,{}
function koStoryStay(own)--6.0 (11-03): in a story, a base-story home town (STAY) becomes a city of that story with a tavern: his own if the story has it, else the first one of his region, then of the nearer regions (NEAR)
if not (own and CONFIG.koCamp) then return own end
if koStoryHomeOf[own]~=nil then return koStoryHomeOf[own] or nil end
if not koStoryInn then
local KC,f=rawget(_G,"koCamp"),rawget(_G,"koWujeNativeTownModels")
if not f then return own end-- the story town models are not loaded yet: ask again later
koStoryInn={}
local cities=(KC and KC.townCities) or {}
local ok,data=pcall(f or function() return {} end)
for _,c in pairs((ok and data) or {}) do for t,td in pairs(c.towns or {}) do if td.inn and cities[t] then koStoryInn[t]=true end end end
end
local r=nil
if koStoryInn[own] then r=own else
for _,g in ipairs(KT.NEAR[REGION_OF[own]] or {}) do for _,t in ipairs(REGION[g] or {}) do if koStoryInn[t] then r=t break end end if r then break end end
end
koStoryHomeOf[own]=r or false
return r
end
