local function ev(n) return JY.Base[KT.EVK..n] or 0 end
local function setev(n,v) JY.Base[KT.EVK..n]=v end
KT.TALK_REP=5-- the fitting answer on a topic already talked about (사용자 "\129\071\134\119 \131\118\134\091 \129\064\129\100\130\098 +5")
-- 820~827: the generals (bit (i-1)%15 of slot 820+floor((i-1)/15)) whose five topics have gone round once
KT.EV_REP=820
local function repeated(i) return math.floor(ev(KT.EV_REP+math.floor((i-1)/15))/2^((i-1)%15))%2==1 end
local function setRepeated(i)
if repeated(i) then return end
local k=KT.EV_REP+math.floor((i-1)/15)
setev(k,ev(k)+2^((i-1)%15))
end
-- 830~837: the generals given a 보물 (once a cycle); 840~847: met on a battlefield, not told in the 주점 yet (bits as 820~827)
local EV_ITEM,EV_MET=830,840
local function bitGet(base,i) return math.floor(ev(base+math.floor((i-1)/15))/2^((i-1)%15))%2==1 end
local function bitSet(base,i,on)
local k,b=base+math.floor((i-1)/15),2^((i-1)%15)
local has=bitGet(base,i)
if on and not has then setev(k,ev(k)+b) elseif not on and has then setev(k,ev(k)-b) end
end
-- 상성 with 유비 (삼국지5의 相性; 사용자 "1~3 \129\103\130\093"): 좋음 = 등용 난이도 -10, 나쁨 = +10, the rest 보통.
-- 좋음: 한실·의협, 유비를 도운 이, 유비의 사람들과 이어진 이 / 나쁨: 조조 핵심과 유비를 죽이자던 모사, 유비를 배신·핍박한 이, 관우를 꺾은 오의 장수
KT.AFFIN={}
for _,n in ipairs({"\130\074\135\089\135\090","\130\124\130\114\133\120","\130\074\135\088","\133\088\133\125","\129\103\133\125","\131\089\134\102","\129\100\135\121\134\090","\130\071\133\113","\130\071\131\071","\135\101\130\110","\131\097\135\112","\129\071\130\125","\135\089\129\067\134\089","\130\114\133\088\130\103","\130\085\135\099\129\126",
"\133\112\133\120","\133\109\133\120","\131\099\129\106","\130\071\132\078","\131\089\130\067\134\100","\129\073\135\112","\134\113\131\076"}) do KT.AFFIN[n]=1 end
for _,n in ipairs({"\129\118\129\118","\130\114\133\088\131\080","\129\097\133\067\135\093","\129\097\133\067\133\066","\129\118\129\106","\129\118\135\095","\129\118\130\080","\129\118\134\103","\129\118\129\103","\129\070\132\109","\135\106\129\094","\131\081\131\072","\130\108\133\097","\129\071\130\069","\135\106\130\114","\129\098\134\097",
"\129\098\135\126","\133\065\131\097","\134\081\135\089","\135\103\131\079"}) do KT.AFFIN[n]=-1 end
local function wins() return ev(1999) end
local function seed()
local s=ev(EV_SEED)
if s<=0 then math.randomseed(os.time()) s=math.random(1,30000) setev(EV_SEED,s) end
return s
end
local function hash(...)
local h=seed()
for _,v in ipairs({...}) do h=(h*131+(v or 0)*7+17)%1000003 end
return h
end
-- the per-battle counts (대화·시도·선물, rumours) are cleared once the 승리 횟수 has moved on
local function fresh()
local w=wins()
if ev(EV_STAMP)==w then return end
for i=1,#KT.TAV do local s=ev(koGenSlot(i)) setev(koGenSlot(i),s-(s%4096)+(s%256)) end
for k=0,RUMOR_N-1 do setev(EV_RUMOR+k,0) end
setev(EV_STAMP,w)
end
-- won over in an earlier cycle (the 도감 entry is open: he has been in the roster) — free from the start (사용자 "\130\125\132\121\133\088\129\077 \129\077\130\086 \133\086\131\071\130\098 \137\088\132\083\129\068"); set below once the 도감 mapping exists
local carried=function(i) return false end
local function gstate(i)
fresh()
local s=ev(koGenSlot(i))
local f=math.floor
return {aff=s%128,unlocked=f(s/128)%2==1 or carried(i),talks=f(s/256)%4,tried=f(s/1024)%2==1,gifted=f(s/2048)%2==1,topic=f(s/4096)%8}
end
local function gsave(i,g)
g.aff=math.max(0,math.min(100,g.aff))
setev(koGenSlot(i),g.aff+(g.unlocked and 128 or 0)+g.talks*256+(g.tried and 1024 or 0)+(g.gifted and 2048 or 0)+(g.topic%8)*4096)
end
function koTavernState(i) return gstate(i),KT.TAV[i] end-- for test scripts

-- the town (with a 주점, open now in this chapter) a tavern general stays in, or nil (not a tavern general / nowhere open):
-- one of the open towns of his region (his own town counts twice), else of a neighbouring region (ADJ; none open: he is nowhere this time); which one is
-- drawn again after every battle (the 승리 횟수 in the hash)
function koTavernStay(name)
local own=koStoryStay(KT.STAY[name]) or (rawget(_G,"koNewGenHome") and koNewGenHome(name)) or (rawget(_G,"koStoryHome") and koStoryHome(name))-- 5.0 (10-12): user generals (newgen) have their own 연고
if own==nil then return nil end
local c=chapter()
if c==nil then return nil end
local home=(T and T.home) or JY.Base[LOC]
local function ok(t)
local td=c.towns[t]
return td~=nil and td.inn~=nil and (t==home or koTownCanGo(c.key,home,t,JY.EventID))
end
if ok(own) then return own end--6.0 (11-03): his home town whenever it is open (no more drawing another town of the region); the rest below = wandering while it is closed
local cand={}
for _,g in ipairs((c.link and {REGION_OF[own]}) or KT.ADJ[REGION_OF[own]] or {}) do
for _,t in ipairs(REGION[g]) do if ok(t) then cand[#cand+1]=t if t==own then cand[#cand+1]=t end end end
if #cand>0 then break end
end
-- 10-19 (카페 제보, 사용자): no open town in his region or the next ones (하북·동 사건 348~630, 4장 성도 593~599 등) → the nearest
-- region with one (NEAR order) instead of nowhere; the 외전 stays own region only
if #cand==0 and not c.link then
for _,g in ipairs(KT.NEAR[REGION_OF[own]] or {}) do
for _,t in ipairs(REGION[g] or {}) do if ok(t) then cand[#cand+1]=t end end
if #cand>0 then break end
end
end
if #cand==0 and KT.STAY[name]==nil and rawget(_G,"koStoryHome") and koStoryHome(name) then for t,_ in pairs(c.towns) do if ok(t) then cand[#cand+1]=t end end table.sort(cand) end-- 5.1 storyhire (10-14): a story general wanders to any open inn
if #cand==0 then return nil end
return cand[hash(wins(),TAV_BYNAME[name] or #name,3)%#cand+1]
end

-- 술꾼's rumours: up to two tavern generals the tavern offers now (not mine, not won over yet) staying in another town;
-- each heard one is kept (slots 702~707) for the 견문록 소문 page until the next battle
local function nsum(s) local n=0 for k=1,#(s or "") do n=n+string.byte(s,k)*k end return n end
local function rumours(town)
fresh()-- (QA: a new battle's rumours must not be added to the last one's and then wiped)
local A={}
local ok,av=pcall(rawget(_G,"koRecAvail") or function() return {} end)
if ok and type(av)=="table" then for c,_ in pairs(av) do local i=TAV_BYNAME[JY.Person[c][P_NAME]] if i then A[i]=true end end end
local un=rawget(_G,"koUnlock")
for _,v in ipairs({407,408,409}) do if un and JY.PersonNum>v and un(v) then A[TAV_IDX[v]]=true end end
local list={}
for i,_ in pairs(A) do
local pid=KT.TAV[i][1]
local at=koTavernStay(KT.TAV[i][2])
if at and at~=town and JY.Person[pid][P_LORD]~=1 then list[#list+1]={i=i,at=at,k=hash(wins(),i,T and nsum(T.town) or 0,5)} end
end
table.sort(list,function(a,b) if a.k~=b.k then return a.k<b.k end return a.i<b.i end)
local out={}
for n=1,math.min(2,#list) do
out[n]=list[n]
local i=list[n].i
for k=0,RUMOR_N-1 do
local v=ev(EV_RUMOR+k)
if v==i then break end
if v==0 then setev(EV_RUMOR+k,i) break end
end
end
return out
end
local function rumourLine(town)
local r=rumours(town)
if #r==0 then return "\129\090\138\114\131\098 \129\071\138\081\129\077 \129\088 \129\109\133\090\129\071 \130\097\130\119\131\096. \131\091 \130\095\131\078 \131\072\129\071\131\118 \129\111\137\120 \129\097\130\067." end
local s="\131\091\133\101\131\100 \131\115\129\076 "..KT.TAV[r[1].i][2]..KT.TAV[r[1].i][3].." \129\090\138\114 "..r[1].at.." \130\075\135\070\129\102 \133\120\130\075 \131\082\135\077\129\077\132\108\130\084."
if r[2] then s=s.." "..KT.TAV[r[2].i][2]..KT.TAV[r[2].i][3].." "..r[2].at.."\129\102 \138\099\131\065\131\100 \132\079\129\077\130\098 \136\124\129\068 \131\082\132\107\129\109." end
return s
end

-- the 등용 difficulty: the bigger the name (출진 코스트 등급, or the hire price without the cost addon) the harder
local function diff(pid,price)
local f=rawget(_G,"koCostOf")
local okc,t=pcall(f or function() return 0 end,pid)
t=okc and tonumber(t) or 0
if t<1 then t=(price>=11000 and 9) or (price>=6000 and 7) or (price>=3000 and 5) or 3 end
if t<=3 then return 0 elseif t<=5 then return 10 elseif t<=7 then return 20 end
return 30
end
local function affin(i) return (i and KT.AFFIN[KT.TAV[i][2]]) or 0 end
local function affinWord(a) return (a>0 and "\138\111\130\077") or (a<0 and "\131\118\144\076") or "\131\115\132\119" end
local function affinColor(a) return (a>0 and RGB(80,190,90)) or (a<0 and RGB(220,90,80)) or M_Silver end
local function chance(g,pid,price)
local d=math.max(0,diff(pid,price)-10*affin(TAV_IDX[pid]))
return math.max(5,math.min(95,g.aff-d))
end
local function chanceWord(p) return (p>=70 and "\137\069\130\077") or (p>=40 and "\131\115\132\119") or (p>=15 and "\137\105\130\077") or "\138\115\136\123\137\072" end
-- the card of the tavern list (jymain HirePerson, 마을 주점): 호감 or 해금
-- 관계 단계 (사용자: 막대 회색·노랑·초록): 0~29 경계, 30~59 호의, 60~ 신뢰 (the greetings change at the same marks), 해금 = 마음을 얻음
local function tier(g)
if g.unlocked then return "\133\088\130\077\129\083 \133\086\130\077",RGB(80,190,90) end
if g.aff>=60 then return "\131\078\132\098",RGB(80,190,90) end
if g.aff>=30 then return "\134\113\131\080",RGB(230,200,60) end
return "\131\064\132\084",RGB(150,150,150)
end
-- the 10-cell bar of 호감 at x,y (cw = a cell's width)
local function affBar(g,x,y,cw,ch)
local _,col=tier(g)
local n=g.unlocked and 10 or math.floor(g.aff/10)
for k=0,9 do
local cx=x+k*(cw+2)
lib.FillColor(cx,y,cx+cw,y+ch,(k<n) and col or RGB(40,44,70))
if k==n and not g.unlocked and g.aff%10>0 then lib.FillColor(cx,y,cx+math.floor(cw*(g.aff%10)/10),y+ch,col) end-- the part of the next ten
lib.DrawRect(cx,y,cx+cw,y,M_Gray) lib.DrawRect(cx,y+ch,cx+cw,y+ch,M_Gray)
lib.DrawRect(cx,y,cx,y+ch,M_Gray) lib.DrawRect(cx+cw,y,cx+cw,y+ch,M_Gray)
end
end
-- the card of the tavern list (jymain HirePerson, 마을 주점): the 단계 on top of his picture, a thin bar at its foot
function koTavernCard(pid,x,y)
local i=pid and TAV_IDX[pid]
if not i then return end
local g=gstate(i)
local word,col=tier(g)
lib.Background(x,y,x+48,y+18,80)
DrawString(x+1,y+1,g.unlocked and "\129\066\131\103" or word,col,16)
lib.Background(x,y+40,x+48,y+48,80)
local w=g.unlocked and 46 or math.floor(46*g.aff/100)
if w>0 then lib.FillColor(x+1,y+42,x+1+w,y+46,col) end
end
-- the 도감 entry (the canonical record) → TAV index, by name (닮은 이름 우금: the tavern's is 牛金, record 171)
local CANON,CANONOF=nil,{}
local function canonIdx(c)
if CANON==nil then
local f=rawget(_G,"koRecCanonOf")
if not f then return nil end
f(1)
local by=CC.koRecByName or {}
CANON={}
for i,r in ipairs(KT.TAV) do local cc=(r[1]==493) and 171 or by[r[2]] if cc and cc>0 then CANON[cc]=i CANONOF[i]=cc end end
end
return CANON[c]
end
carried=function(i)
local met=rawget(_G,"koRecMet")
if not met then return false end
canonIdx(0)
local c=CANONOF[i]
return c~=nil and met(c)
end
-- the 도감 (사용자 "\133\098\129\114 \129\118\129\119, \133\066\131\100 \129\071\138\081\129\081 \130\119\135\076\129\066\131\087"): two parts — when he turns up in the taverns, and his own town. Where else he
-- is staying is left to the 술꾼's rumours (사용자 "\133\066\131\100\130\067 \129\071\131\107\129\102\130\098 \132\076\137\110\131\076\131\109\132\083 \130\083\131\090 \132\079\129\077\131\100 \133\113\130\086\129\097\130\067 \136\124 \131\117").
local function plainCut(s,pre)-- s without its leading pre (plain bytes: hz codes are no patterns)
if string.sub(s,1,#pre)==pre then return string.sub(s,#pre+1) end
return s
end
local function condOf(s)-- the record's condition line without "\131\072\134\076 \161\164 " (every tavern line starts so)
s=plainCut(s or "","\131\072\134\076 \161\164 ")
return s
end
-- the locked panel's text (t = the record's own: "\133\125\132\111 \129\118\129\119*<condition>[*\129\103\130\093 \161\173]", '*' = new line) rebuilt in two parts
function koTavStoryOwn(own,cond)--6.0 (11-03): in a story only a tavern general (his condition names the tavern) gets the base-story home town / affinity
if own and CONFIG.koCamp and not (string.find(cond or "","\130\075\135\070",1,true) or string.find(cond or "","\131\072\134\076",1,true)) then return nil end
return own
end
function koTavStayNote(i,own,short)--6.0 (11-03): the home line as things are now: at home / wandering (where: the drinkers' rumours) / the rule (no game)
local ok,at=pcall(koTavernStay,KT.TAV[i][2])
if not ok then at=nil end
if at and at~=own then return short and "(\130\067\131\103\131\098 \133\066\131\100\129\102 \135\121 \129\113 \130\097\130\083 \132\078\135\124 \130\101 \161\164 \130\110\132\081\130\098 \131\072\137\091 \129\109\133\090\131\109\132\083)" or "*\130\067\131\103\131\098 \133\066\131\100\129\102 \135\121 \129\113 \130\097\130\083 \132\078\135\124 \130\101*(\130\110\132\081\130\098 \131\072\137\091 \129\109\133\090\131\109\132\083)" end
if at==own then return short and "(\135\121 \129\113 \132\079\130\098 \130\108\130\111\131\098 \131\088 \129\071 \133\088\129\083 \130\075\135\070)" or "*\135\121 \129\113 \132\079\130\098 \130\108\130\111\131\098 \131\088 \129\071 \133\088\129\083 \130\075\135\070" end
return short and "(\135\121 \129\113 \130\097\130\098 \130\108\130\111\131\098 \130\075\130\116 \133\088\129\083\132\083 \132\078\135\124)" or "*\135\121 \129\113 \130\097\130\098 \130\108\130\111\131\098 \130\075\130\116 \133\088\129\083\132\083 \132\078\135\124"
end
function koTavernWhereText(c,t)
local i=canonIdx(c)
local own=i and koStoryStay(KT.STAY[KT.TAV[i][2]])
local cond=plainCut(t or "","\133\125\132\111 \129\118\129\119")
cond=plainCut(cond,"*")
own=koTavStoryOwn(own,cond)
if not own then return "\161\190\133\098\129\114 \129\118\129\119\161\191*"..cond end-- 이야기 합류·숨은 인재: the same heading as the hover box
cond=condOf(cond)
return "\161\190\133\098\129\114 \129\118\129\119\161\191*"..cond.."* *\161\190\133\066\131\100\161\191*"..own.." \130\075\135\070"..koTavStayNote(i,own).."*\129\067\131\123 "..affinWord(affin(i)).." (\133\125\132\111 \130\113\129\071\129\068\129\102 \129\126\134\089)*\130\075\135\070\129\102\131\087 \129\071\133\069\131\071\132\083 \134\113\135\078\129\083 \144\067\129\110 \133\125\132\111"
end
-- the 무장 전적 of a 도감 entry (사용자: 전적 탭 대신 도감 상자에): 출전 · 격파 · 준 피해 · MVP, a tavern copy counted on its entry
-- (as the old tab's koCareerRank did); nil when there is nothing yet
local function careerLine(c)
local co,rec=rawget(_G,"koCareerOf"),rawget(_G,"koRec")
if not (co and rec) then return nil end
local mvf=rawget(_G,"koMVPCount")
local k,mv,so,dm=0,0,0,0
for p=1,math.min(JY.PersonNum-1,601) do-- 5.1 storyhire
local key=p
if p>=421 then local cc=koRecCanonOf(p) if cc and cc>0 then key=cc end end
if p==493 then key=171 end
if key==c then
local r=co(p)
k=k+rec(1200+p) mv=math.max(mv,mvf and mvf(p) or 0) so=math.max(so,r.sorties) dm=math.max(dm,r.dmg)
end
end
if k==0 and mv==0 and so==0 then return nil end
local d=(dm>=100000) and string.format("%.1f\132\086",dm/10000) or tostring(dm)
return "\133\098\130\066 "..so.." \161\164 \130\112\134\086 "..k.." \161\164 \131\101 \137\088\129\066 "..d.." \161\164 MVP "..mv
end
-- the 도감's hover box by a card (x,y = the card): 출현 조건 / 연고 (tavern generals), 전적 (open entries), labels in a column
function koTavernTip(c,x,y,recordStyle,classicFrame)
if rawget(_G,"koRecHidden") and koRecHidden(c) then return end-- the hidden ones stay hidden until the tavern has offered them
local rows={}
local i=canonIdx(c)
local own=i and koStoryStay(KT.STAY[KT.TAV[i][2]])
-- every entry: how he turns up (이야기 합류 · N장 OO 전투 / the tavern condition without its "\131\072\134\076 \161\164 " / 3장 도시 순회 …)
local h=rawget(_G,"koRecHint") and koRecHint[c]
local cond=h and string.match(h,"\t(.*)$")
own=koTavStoryOwn(own,cond)
if rawget(_G,"koBookNeutral") then own=nil end--ko 11-11: the main screen's merged book: no story's own home / affinity lines
if cond and cond~="" then rows[#rows+1]={"\133\098\129\114 \129\118\129\119",own and condOf(cond) or cond} end
if own then rows[#rows+1]={"\133\066\131\100",own.."  "..koTavStayNote(i,own,true)} rows[#rows+1]={"\129\067\131\123",affinWord(affin(i)).."  "..(CONFIG.koCamp and "(\130\075\130\084\129\123\131\080 \134\088\129\087: \133\125\132\111 \130\113\129\071\129\068\129\102 \129\126\134\089)" or "(\130\071\130\080\135\122\131\080 \134\088\129\087: \133\125\132\111 \130\113\129\071\129\068\129\102 \129\126\134\089)")} end
if koRecUnlocked(c) then-- (also on the title's record screen: the bits are in the loaded record)
local cl=careerLine(c)
rows[#rows+1]={"\130\066\131\076",cl or "\129\110\132\076 \131\071\133\108 \130\097\130\077"}
end
if #rows==0 then return end
local LW=88-- the label column
local lines={}-- {label or nil, text}: a long value goes on over more lines (at most 46 bytes = 23 letters a line)
local function koStar(s)--ko 11-11: '*' = a new line (the hint text's own mark); a hz code's second byte is skipped, not split
local t,b,i={},1,1
while i<=#s do local v=string.byte(s,i) if v>=128 then i=i+2 elseif v==42 then t[#t+1]=string.sub(s,b,i-1) i=i+1 b=i else i=i+1 end end
t[#t+1]=string.sub(s,b)
return t
end
for _,r in ipairs(rows) do
local first=true
for _,seg in ipairs(koStar(r[2])) do for k,l in ipairs(wrap(seg,46)) do lines[#lines+1]={first and r[1] or nil,l} first=false end end
end
local w=0
for _,l in ipairs(lines) do w=math.max(w,#l[2]*8) end
local pad=recordStyle and 12 or 8
w=w+LW+pad*2+4
local step=recordStyle and 25 or 22
local h2=#lines*step+pad*2
local border=recordStyle and M_Silver or M_Gray
local bx=x+76
if bx+w>CC.ScreenW-8 then bx=x-8-w end
if bx<8 then bx=8 end
local by=math.max(8,math.min(y,CC.ScreenH-h2-40))-- above the 이전·다음 row
if recordStyle and classicFrame then
classicFrame(bx,by,w,h2)
else
lib.FillColor(bx,by,bx+w,by+h2,RGB(8,12,48))
lib.DrawRect(bx,by,bx+w,by,border) lib.DrawRect(bx,by+h2,bx+w,by+h2,border)
lib.DrawRect(bx,by,bx,by+h2,border) lib.DrawRect(bx+w,by,bx+w,by+h2,border)
end
lib.DrawRect(bx+LW,by+pad,bx+LW,by+h2-pad,border)
for k,l in ipairs(lines) do
local ry=by+pad+(k-1)*step
if l[1] then DrawString(bx+pad,ry,l[1],C_Name,16) end
