-- 도감의 해금 (5.0, 사용자 "\129\068\135\078\131\080 \129\066\131\103 = \130\095\129\064\129\102 \131\123\130\074\129\066 \129\073\129\085\132\083 \133\125\132\111\129\088 \129\113 \132\079\129\081 \144\091"): a tavern general's entry opens once he has
-- been won over — he joins at once, so it is the record's "been in the roster" bit (1840, kept across cycles). Being offered by
-- the tavern (bit 1810, koRecSeen) now only lifts the ??? of the hidden ones. Everyone else: as before.
local recUnlocked=rawget(_G,"koRecUnlocked")
if recUnlocked and rawget(_G,"koRecMet") then
function koRecUnlocked(c)
if canonIdx(c) then return koRecMet(c) end
return recUnlocked(c)
end
