local function tavernMeet(pid,price)
local i=TAV_IDX[pid]
local K=rawget(_G,"koTavTalk")
local d=K and i and K[pid]
local name=JY.Person[pid][P_NAME]
if d==nil then-- no lines for him: the old purchase
if WarDrawStrBoxYesNo("\130\080\132\111 "..price.."\131\103, \133\125\132\111: "..name..". \131\074\131\075\129\075\129\076\129\089?",M_White,true) then
