talk(pid,(g.unlocked or g.aff>=60) and d.warm or (g.aff>=30 and d.mid) or d.first)
if bitGet(EV_MET,i) then-- 격파·일기토 감복: told once, the 호감 was added on the battlefield
bitSet(EV_MET,i,false)
WarDrawStrBoxConfirm(name..KT.TAV[i][3].." \130\066\131\097\129\102\131\087 "..JY.Person[1]["\208\213\195\251"].."\130\084\129\123 \138\071\140\069\132\107\138\066 \133\073\129\083 \131\071\132\070\129\097\131\100 \132\079\129\077.*\131\091\132\085\131\080 \139\077\131\084\130\104 \139\088\131\105\129\117\134\066 \129\077\130\086 \131\115\129\081 \136\089 \135\075\129\097\129\077.",M_White,true)
end
while true do
g=gstate(i)
local p=chance(g,pid,price)
local menu,act={},{}
