if g.unlocked then add("\133\125\132\111\129\111\129\077 (\129\073\129\085)","hire")
else
if g.talks<TALKS then add("\129\071\133\069\131\071\129\111\129\077 (\133\103\131\098 "..(TALKS-g.talks).."\130\087)","talk") end
if not g.tried then add("\133\125\132\111\129\083 \137\082\129\111\129\077 (\131\103 "..cost..")","try") end
if g.tried and not g.gifted then add("\131\103\129\083 \131\101\129\077 (\131\103 "..gcost..")","gift") end
if not bitGet(EV_ITEM,i) then add("\131\115\131\065\129\083 \131\101\129\077 (\129\111 \130\087)","item") end
end
if #menu==0 then
WarDrawStrBoxConfirm("\129\077\130\077 \130\066\132\101\129\094 \139\091\131\083 \132\085\129\089\130\067\130\098*"..name..(KT.TAV[i][3]=="\129\071" and "\129\123" or "\135\122").." \132\108 \129\071\133\069\131\071\129\088 \129\113 \130\097\129\075\129\076\129\077.",M_White,true)
return
end
add("\137\066\129\110\133\121\129\077","leave")
DrawSMap()
relPanel(pid,i,g,p)
local r=ShowMenu(menu,#menu,0,0,156,0,0,3,1,16,M_White,M_White)
local a=act[r] or "leave"
if a=="leave" then PlayWavE(1) return
elseif a=="hire" then
if WarDrawStrBoxYesNo(name.."\129\083(\130\104) \130\094\129\097\132\083 \129\124\129\083\129\089\129\090?",M_White,true) then talk(pid,d.yes) hireNow(pid) return end
elseif a=="talk" then
local tp=d.topics[(g.topic%#d.topics)+1]
talk(pid,tp[1])
local pm=KT.PERM[hash(wins(),i,g.talks,g.topic,11)%6+1]
local cm={}
for k=1,3 do cm[k]={tp[pm[k]+1][1],nil,1} end
local cr=0
while cr<=0 or cr>3 do
