if dv>=TALK_UP then PlayWavE(11) DrawStrBoxCenter(name.."\131\080 \134\113\135\078\129\071 \131\105\132\103\129\077. (+"..dv..")")
elseif ch[2]>=10 then DrawStrBoxCenter("\129\071\134\119 \131\118\132\073 \129\071\133\069\131\071\130\102 "..name.."\131\080 \134\113\135\078\129\071 \129\118\131\103 \131\105\132\103\129\077. (+"..dv..")")
elseif ch[2]>0 then DrawStrBoxCenter(name.."\131\080 \134\113\135\078\129\071 \129\118\131\103 \131\105\132\103\129\077. (+"..dv..")")
else PlayWavE(2) DrawStrBoxCenter(name.."\131\080 \134\113\135\078\129\071 \132\110\130\083\131\070\129\077. ("..dv..")") end
