if hash(wins(),i,77,g.aff,g.talks)%100<p then-- (QA: the 호감 is in the roll — a failure tells nothing about a retry after reloading and talking more)
g.unlocked=true gsave(i,g)
if rawget(_G,"koRecMeet") then koRecMeet(pid) end-- 도감 해금 now (won over), and free in the cycles to come
talk(pid,d.yes)
PlayWavE(11)
-- 사용자 "\131\123\130\074 \132\076\133\067 \131\065\130\083\131\115\131\071": take him now, or leave him won over and take him later for nothing
