WarDrawStrBoxConfirm("\130\075\135\070\129\102\131\087 \129\077\130\086 \132\086\131\118\129\065 \129\073\129\085\132\083 \133\104\131\096\135\121 \129\113 \132\079\129\075\129\076\129\077.*(\133\066\131\100 \133\088\129\083\129\102 \135\121 \129\113 \132\079\131\109\129\065 \131\088 \131\091 \130\075\135\070\129\102 \132\079\129\075\129\076\129\077.)",M_White,true)
else
talk(pid,d.no)
PlayWavE(2)
DrawStrBoxCenter("\133\125\132\111\129\102 \129\078\129\079\129\080\129\077.")
end
end
end
elseif a=="item" then
