local list={}
for p=1,JY.PersonNum-1 do
if JY.Person[p][P_LORD]==1 then
pcall(ReSetAttrib,p,false)-- 武器·防具·辅助 = the best of the bag, kept up to date by ReSetAttrib
local eq={}
for _,k in ipairs({K_WEAPON,K_ARMOR,K_AUX}) do local v=JY.Person[p][k] if v and v>0 then eq[v]=true end end
for s=1,8 do local iid=JY.Person[p][K_ITEM..s] if iid and iid>0 and not eq[iid] and not exclusive(iid) then list[#list+1]={p,s,iid} end end
end
