else
local im={}
for k,rw in ipairs(list) do im[k]={fillblank(JY.Item[rw[3]][I_NAME],13)..JY.Person[rw[1]][P_NAME],nil,1} end
DrawSMap()
relPanel(pid,i,g,p)
