for n=rw[2],7 do JY.Person[rw[1]][K_ITEM..n]=JY.Person[rw[1]][K_ITEM..(n+1)] end-- out of the bag, the rest moves up (as 버리기)
JY.Person[rw[1]][K_ITEM.."8"]=0
pcall(ReSetAttrib,rw[1],false)
bitSet(EV_ITEM,i,true)
