talk(ME(),"\136\072\129\111 \131\065\129\119\129\071\130\067\132\086 \131\091\130\095\129\102\129\081 \133\119\129\117\131\100 \138\093\129\109. \133\072\129\110 \130\075\130\086\129\091.")
if v>=20 then PlayWavE(11) end
DrawStrBoxCenter(msg.." (+"..v..")")
end
end
elseif a=="gift" then
if WarDrawStrBoxYesNo("\131\103 "..gcost.."\129\083 \132\123\129\089\129\090?",M_White,true) then
