elseif d.gift[1]>0 then DrawStrBoxCenter(name.."\131\080 \134\113\135\078\129\071 \131\105\132\103\129\077. (+"..d.gift[1]..")")
else PlayWavE(2) DrawStrBoxCenter(name.."\131\080 \134\113\135\078\129\071 \132\110\130\083\131\070\129\077. ("..d.gift[1]..")") end
