function koTownStageData() return KT.STAGE,DATA end-- for test scripts
function koTownStageT(ck,town,key,i) return revisitLine(DATA[ck],town,key,i) end-- for test scripts
-- 격파·일기토 감복 (삼국지5의 포로 등용 맛): in a story battle (not a free / town / replay one, so it cannot be farmed),
-- beating an enemy general whose tavern copy is not won over yet adds to that copy's 호감 — 격파 +5 (once a battle),
-- 일기토 승리 +15 — and he says so the next time he is met in a 주점 (bit 840~847)
local beatenWar={}
koOn("war_begin",function() beatenWar={} end)
local function credit(pid,amount)
if not CC.Enhancement or CC.koFree or CC.koTownBattle or CC.koReplay then return end
local nm=JY.Person[pid][P_NAME]
local i=TAV_BYNAME[nm]
if not i then return end
if KT.TAV[i][1]==493 and pid~=171 then return end-- 우금: the tavern's is 牛金 (record 171), not 于禁
if JY.Person[KT.TAV[i][1]][P_LORD]==1 then return end
local g=gstate(i)
if g.unlocked then return end
g.aff=g.aff+amount gsave(i,g)
bitSet(EV_MET,i,true)
end
function koTavernCreditT(pid,amount) return credit(pid,amount) end-- for test scripts
koOn("unit_down",function(wid,atk)
local v=War.Person[wid]
local a=atk and War.Person[atk]
if not v or not a or a.enemy or a.friend or beatenWar[v.id] then return end
beatenWar[v.id]=true
credit(v.id,5)
end)
local oldFight=rawget(_G,"fight")
if oldFight then
function fight(a,b,sid)
local r=oldFight(a,b,sid)
pcall(function()
local me,foe
if r==1 then me,foe=a,b elseif r==2 then me,foe=b,a else return end
if JY.Status==GAME_WMAP and JY.Person[me][P_LORD]==1 and JY.Person[foe][P_LORD]~=1 then credit(foe,15) end-- battles only (the 무술 대회 duels too go through fight)
end)
return r
end
end
function koTavernMeetT(pid,price) return tavernMeet(pid,price) end-- for test scripts
function koTavernRumourT(town) return rumourLine(town) end-- for test scripts
-- the 주점's list: HirePerson with only the generals staying here; picking one (koTavernPick) leaves the list for the meeting,
-- then the list comes back until it is closed
local function tavernHire(town)
while true do
CC.koTavernTown=town
CC.koTavernPick=(CC.Enhancement and rawget(_G,"koTavTalk")~=nil) or nil-- 클래식 모드: the old purchase
local ok,err=pcall(HirePerson)
local pick=CC.koTavernPick
CC.koTavernTown=nil CC.koTavernPick=nil
if not ok then error(err,0) end
if type(pick)~="table" then return end
tavernMeet(pick.pid,pick.price)
DrawSMap()
end
end
-- 11-12 카페 건의 (다회차 술집 해금 무장 한 번에 영입): 주점 주인에게 「마음을 얻은 무장을 모두 부른다」.
--  대상 = 지금 주점 목록에 나올 무장(HirePerson 을 목록 만들기까지만 돌려 같은 조건 · 레벨) 중 마음을 얻은(지난 회차 해금 포함 = 무료) 무장으로,
--  머무는 마을(연고 · 떠돎)과 상관없이 부름. 비용 없음 (원래도 무료)
local function wonAll()
if koStoryEv()<koHireFromEv() then return {} end
local got,order={},{}
local rawStay,rawConf=koTavernStay,WarDrawStrBoxConfirm
local rawTown,rawPick=CC.koTavernTown,CC.koTavernPick
koTavernStay=function(name)
for k,p in ipairs(TeamSelect.id) do
if TeamSelect.status[k]==0 and not got[p] and JY.Person[p][P_NAME]==name then got[p]=true order[#order+1]=p end
end
return nil
end
WarDrawStrBoxConfirm=function() return true end
CC.koTavernTown="\001all" CC.koTavernPick=nil
local ok,err=pcall(HirePerson)
koTavernStay=rawStay WarDrawStrBoxConfirm=rawConf CC.koTavernTown=rawTown CC.koTavernPick=rawPick
if not ok then error(err,0) end
local t={}
for _,p in ipairs(order) do
local i=TAV_IDX[p]
if i and JY.Person[p][P_LORD]~=1 and gstate(i).unlocked then t[#t+1]=p end
end
return t
end
function koTavernWonAllT() return wonAll() end-- for test scripts
local function namesText(list)
local s,line={},{}
for n,p in ipairs(list) do
if n>18 then s[#s+1]="\131\107 "..(#list-18).."\130\088" break end
line[#line+1]=JY.Person[p][P_NAME]
if #line==6 then s[#s+1]=table.concat(line," \161\164 ") line={} end
end
if #line>0 and #list<=18 then s[#s+1]=table.concat(line," \161\164 ") end
return table.concat(s,"*")
end
local function hireAll(list)
if not WarDrawStrBoxYesNo("\133\088\130\077\129\083 \133\086\131\098 \129\073\131\097 "..#list.."\130\088\129\083 \130\090\130\091 \130\094\129\097\132\083 \129\124\129\083\129\089\129\090?*"..namesText(list),M_White,true) then return end
local notes={}
local rawConf=WarDrawStrBoxConfirm
WarDrawStrBoxConfirm=function(s) if type(s)=="string" then notes[#notes+1]=s end return true end
local ok,err=pcall(function()
for _,p in ipairs(list) do
if rawget(_G,"koRecMeet") then koRecMeet(p) end
ModifyForce(p,1)
