-- 기록 > 견문록 first page (사용자: 소문 탭은 견문록 안으로): the rumours heard since the last battle (where they are now) and
-- everyone 호감 has been built with; the 견문록's own pages follow
if rawget(_G,"koRecTabs") then
local function rumourPage(c)
if JY.Status==GAME_START or JY.Base==nil then c.ctext(c.oy+200,"\129\081\129\082\129\083 \133\100\133\101\134\091 \135\068\129\102 \133\082 \129\113 \132\079\129\075\129\076\129\077.",M_Gray) return end
fresh()
c.txt(c.ox+24,c.oy+60,"\131\072\137\091\129\102\129\081 \131\082\131\098 \129\109\133\090 (\129\077\130\077 \130\066\132\101\129\089\130\067)",C_Name)
local y=c.oy+90
local any=false
for k=0,RUMOR_N-1 do
local i=ev(EV_RUMOR+k)
if i>0 and KT.TAV[i] then
local at=koTavernStay(KT.TAV[i][2])
c.txt(c.ox+40,y,KT.TAV[i][2]..": "..(at and (at.." \130\075\135\070") or "\130\083\131\090 \132\079\130\098\130\067 \130\090\138\075"),M_White) y=y+21 any=true
end
end
if not any then c.txt(c.ox+40,y,"\130\075\135\070\131\080 \131\072\137\091\129\102\129\081 \136\124\129\083 \130\064\129\065 \129\109\133\090\129\083 \131\082\129\083 \129\113 \132\079\129\075\129\076\129\077.",M_Gray) y=y+21 end
y=y+14
c.txt(c.ox+24,y,"\134\113\135\078",C_Name) y=y+30
local E={}
for i,r in ipairs(KT.TAV) do local g=gstate(i) if g.aff>0 or g.unlocked then E[#E+1]={i=i,g=g} end end
-- QA: by 호감 (won over last), only as many as fit above the page footer, the rest counted
table.sort(E,function(a,b) if a.g.unlocked~=b.g.unlocked then return not a.g.unlocked end if a.g.aff~=b.g.aff then return a.g.aff>b.g.aff end return a.i<b.i end)
local maxn=math.max(0,math.floor((c.oy+420-y)/21))*4
local row,col=0,0
for k,e in ipairs(E) do
if k>maxn or (k==maxn and #E>maxn) then c.txt(c.ox+40+col*180,y+row*21,"\131\107 "..(#E-k+1).."\130\088",M_Gray) break end
local r=KT.TAV[e.i]
c.txt(c.ox+40+col*180,y+row*21,r[2].." "..(e.g.unlocked and "\129\066\131\103" or e.g.aff),(JY.Person[r[1]][P_LORD]==1) and M_Gray or M_White)
col=col+1 if col==4 then col=0 row=row+1 end
end
end
for _,tb in ipairs(koRecTabs) do
if tb.label=="\134\084\133\090\133\108" then
local n0,d0=tb.n,tb.draw
tb.n=function() return n0()+1 end
tb.draw=function(page,c) if page==1 then rumourPage(c) else d0(page-1,c) end end
end
end
end

-- (T, the open town, is declared above the shop helpers)
function koTownState() return T end-- for test scripts

local function feet(x,y) return 27+18*x,19+18*y end
local function row(pid)
for _,v in ipairs(JY.Smap) do if v[1]==pid then return v end end
end
local function arrowRect(x,y)
local fx,fy=feet(x,y)
return fx-44,fy-26,fx+44,fy+26
end
local function tagRect(d)
local fx,fy=feet(d.x,d.y)
local w=#d.label*8+24
return fx-w/2,math.max(20,fy-86),w,28
end
local function overDoor(d,test)
if d.arrow then
local x1,y1,x2,y2=arrowRect(d.x,d.y)
return test(x1,y1,x2,y2)
end
local x,y,w,h=tagRect(d)
local fx,fy=feet(d.x,d.y)
return test(x,y,x+w,y+h) or test(fx-20,fy-60,fx+20,fy)
end
local function townData() return T.chap.towns[T.town] end
local function streetDoor(to)
for _,d in ipairs(townData().street.doors) do if d.to==to then return d end end
end

-- the place `key` ("street" or a room kind) of T.town with 유비 standing at x,y facing dir
local function build(key,x,y,dir)
local td=townData()
local bg,people
if key=="street" then
bg,people=td.street.bg,td.street.people
else
local RM=KT.ROOM[key]
bg,people=RM.bg,{}
for i,r in ipairs(td[key] or {}) do
local s=RM.spots[i]
if s then people[#people+1]={r[1],s[1],s[2],s[3],r[2]} end
end
end
local smap,used,figs={},{},{}
T.lines,T.nick,T.bit={},{},{}
local bix=BOOKIDX[T.chap.key] and BOOKIDX[T.chap.key][T.town] or {}-- 견문록 index of each townsman
local function free(id) return not used[id] and not figs[koTownFig(id)] and not (rawget(_G,"koViewReserved") and koViewReserved(id)) end-- 10-10: not the sisters-in-law while a 외전 scene uses them
local function take(code)
for _,id in ipairs(KT.POOL[code] or {}) do if free(id) then return id end end
for _,id in ipairs(KT.SPARE) do if free(id) then return id end end
return 345
end
-- on the street the townsman by the stall (2nd spot) is the town's 도구상 when the town has a shop (375 도구상: his figure is
-- reserved first so no other townsman shares it)
local sid=key=="street" and (townSpecial(T.town) or (T.chap.key=="\131\107\130\066" and townShop(T.town)>0)) and 1 or 0-- 외전 마을: 특산품이 없어도 도구상(Shop)을 여는 사람
T.shop={}
T.act={}
if sid>0 then used[KT.SHOPKEEPER]=true figs[koTownFig(KT.SHOPKEEPER)]=true end
