-- the 술 겨루기 (drink addon), besides the town's four patrons; their figures are reserved first
local extra={}
if key=="inn" then
extra[#extra+1]={INNKEEPER,19.5,5.5,3,"\130\083\131\087 \129\091\130\086\129\091. \133\073\133\120\129\117\130\104 \139\113\130\098 \130\114\134\118\131\082\129\071 \129\098\131\071 \130\090\129\098 \132\079\129\077\129\091.","hire","\130\075\135\070 \130\075\129\106",{25.5,8.5,2}}-- behind the counter; 유비 talks to him from its right end
