local tid=townTalent()
if tid then extra[#extra+1]={tid,28.5,11,1,"\161\173\161\173(\130\099\133\120 \131\072\137\120\129\083 \131\071\133\091\129\071\134\066 \129\096\130\069\129\102 \135\100\132\125 \132\079\129\077)","talent","\141\072\133\109 \130\114\134\118"} end
end
for _,e in ipairs(extra) do used[e[1]]=true figs[koTownFig(e[1])]=true end
T.talkAt={}
for _,e in ipairs(extra) do
smap[#smap+1]={e[1],e[2],e[3],e[4],0}
T.lines[e[1]]=e[5] T.act[e[1]]=e[6] T.nick[e[1]]=e[7] T.talkAt[e[1]]=e[8]
end
for i,r in ipairs(people) do
local id
if sid>0 and i==2 then id=KT.SHOPKEEPER T.shop[id]=sid else id=take(r[1]) end
used[id]=true figs[koTownFig(id)]=true
smap[#smap+1]={id,r[2],r[3],r[4],0}
T.lines[id]=r[5] T.bit[id]=bix[key..i]
local rv=revisitLine(T.chap,T.town,key,i)
if rv then T.lines[id]=rv T.bit[id]=nil end-- 다시 들른 마을: the news of that time swapped
if id==KT.SHOPKEEPER then local sl=KT.SHOPLINE[T.chap.key] T.lines[id]=sl and sl[T.town] or "\130\083\131\087 \129\091\135\073\130\086\129\091." end
T.nick[id]=(id~=KT.SHOPKEEPER) and KT.NICK[r[1]] or nil
end
smap[#smap+1]={ME(),x,y,dir,0}
JY.Smap=smap
SortPerson()
JY.SubScene=bg
T.cur=key
T.mode="scene"
end

local function frame()
JY.ReFreshTime=lib.GetTime()
if T==nil or T.mode~="region" then SortPerson() end
DrawSMap()
lib.GetKey()
ReFresh(1)
end
-- n steps along dir d (one step = 2 columns and 1 row), a quarter step a frame
local function leg(v,d,n)
if n<0.01 then return end
v[4]=d
v[5]=1
while n>0 do
local s=math.min(0.25,n)
v[2]=v[2]+CC.DX[d]*s
v[3]=v[3]+CC.DY[d]*s
n=n-s
frame()
end
v[5]=0
end
