local function lerp(t,u)-- the line value at u of points {u,v}
if u<=t[1][1] then return t[1][2] end
for i=2,#t do if u<=t[i][1] then local a,b=t[i-1],t[i] return a[2]+(b[2]-a[2])*(u-a[1])/(b[1]-a[1]) end end
return t[#t][2]
end
local function blocked(B,x,y)
for _,r in ipairs(B.rects or {}) do if x>r[1] and x<r[3] and y>r[2] and y<r[4] then return true end end
if B.top and y<lerp(B.top,x) then return true end
if B.bot and y>lerp(B.bot,x) then return true end
if B.left and x<lerp(B.left,y) then return true end
for _,s in ipairs(B.segs or {}) do
local ux,uy=s[3]-s[1],2*(s[4]-s[2])
local wx,wy=x-s[1],2*(y-s[2])
local t=math.max(0,math.min(1,(wx*ux+wy*uy)/(ux*ux+uy*uy)))
local ex,ey=wx-ux*t,wy-uy*t
if ex*ex+ey*ey<KT.BENCH*KT.BENCH then return true end
end
return false
end
function koTownBlocked(bg,x,y) return KT.BLOCK[bg]~=nil and blocked(KT.BLOCK[bg],x,y) end-- for test scripts
-- the turning point of a walk from (x0,y0) to (x,y): first = true -> the dir-0/1 leg first
local function turn(x0,y0,x,y,first)
local dx,dy=x-x0,y-y0
if first then local a=(dx/2-dy)/2 return x0+2*a,y0-a end
local b=(dx/2+dy)/2 return x0+2*b,y0+b
end
local function clearLine(B,x0,y0,x1,y1,ex,ey,sx,sy)
local n=math.max(1,math.ceil(math.max(math.abs(x1-x0)/2,math.abs(y1-y0))*4))
for i=0,n do
local x,y=x0+(x1-x0)*i/n,y0+(y1-y0)*i/n
if x<0 or x>35 or y<1 or y>22 then return false end-- off the picture
if (x-ex)^2+(2*(y-ey))^2>1.5 and (x-sx)^2+(2*(y-sy))^2>1.5 then-- the spots he walks from and to may stand against a wall
if blocked(B,x,y) then return false end
end
end
return true
end
local function len(x0,y0,mx,my,x,y) return math.abs(mx-x0)+math.abs(my-y0)*2+math.abs(x-mx)+math.abs(y-my)*2 end
-- the points 유비 passes from (x0,y0) to (x,y) (turning points and hubs), or the middle rule when the picture has no furniture list
function koTownRoute(bg,x0,y0,x,y)
local B=KT.BLOCK[bg]
local best,bl
local function try(pts)
local l=0
for i=2,#pts do
if B and not clearLine(B,pts[i-1][1],pts[i-1][2],pts[i][1],pts[i][2],x,y,x0,y0) then return end
l=l+math.abs(pts[i][1]-pts[i-1][1])+2*math.abs(pts[i][2]-pts[i-1][2])
end
if not bl or l<bl then best,bl=pts,l end
end
local ax,ay=turn(x0,y0,x,y,true)
local bx,by=turn(x0,y0,x,y,false)
local amid=(ax-17)^2+(2*(ay-11))^2<=(bx-17)^2+(2*(by-11))^2
local p1={{x0,y0},{ax,ay},{x,y}}
local p2={{x0,y0},{bx,by},{x,y}}
if not B then return amid and p1 or p2 end
try(amid and p1 or p2)
if best then return best end
try(amid and p2 or p1)
if best then return best end
-- neither way round is clear: search the half-step lattice of the iso axes from (x0,y0) (state = a,b steps and the last dir,
-- a step costs 1 and a turn 3, so the fewest turns win), to the lattice point next to (x,y), then the last short two legs
local SA={[0]=1,-1,0,0}-- dir 0 +a, 1 -a, 2 -b, 3 +b
local SB={[0]=0,0,-1,1}
local function px(i,j) return x0+i+j,y0-i*0.5+j*0.5 end
local ta,tb=(x-x0)/2-(y-y0),(x-x0)/2+(y-y0)-- target in half steps
local gi,gj=math.floor(ta+0.5),math.floor(tb+0.5)
local function search(B)
local function key(i,j,d) return ((i+100)*201+(j+100))*4+d end
local dist,prev={},{}
local buckets={[0]={}}
for d=0,3 do local k=key(0,0,d) dist[k]=0 buckets[0][#buckets[0]+1]={0,0,d} end
local found
for c=0,600 do
local bq=buckets[c]
if bq then
for _,s in ipairs(bq) do
local i,j,d=s[1],s[2],s[3]
local k=key(i,j,d)
if dist[k]==c then
if i==gi and j==gj then found=k break end
for nd=0,3 do
local ni,nj=i+SA[nd],j+SB[nd]
local nx,ny=px(ni,nj)
if nx>=0 and nx<=35 and ny>=1 and ny<=22 and math.abs(ni)<100 and math.abs(nj)<100 then
local free=(nx-x)^2+(2*(ny-y))^2<=1.5 or (nx-x0)^2+(2*(ny-y0))^2<=4 or not blocked(B,nx,ny)
if free then
local nc=c+1+(nd~=d and 3 or 0)
local nk=key(ni,nj,nd)
if not dist[nk] or nc<dist[nk] then
dist[nk]=nc prev[nk]=k
buckets[nc]=buckets[nc] or {}
local nb=buckets[nc] nb[#nb+1]={ni,nj,nd}
end
end
end
end
end
end
if found then break end
end
end
if not found then return nil end
-- back from the goal, keeping the points where the dir changes
local cells={}
local k=found
while k do
local d=k%4 local r=(k-d)/4 local j=r%201-100 local i=(r-(j+100))/201-100
table.insert(cells,1,{i,j,d})
k=prev[k]
end
local pts={{x0,y0}}
for n=2,#cells do
if n==#cells or cells[n+1][3]~=cells[n][3] then local qx,qy=px(cells[n][1],cells[n][2]) pts[#pts+1]={qx,qy} end
end
local lx,ly=pts[#pts][1],pts[#pts][2]
if math.abs(lx-x)>0.01 or math.abs(ly-y)>0.01 then
local tx,ty=turn(lx,ly,x,y,true)
pts[#pts+1]={tx,ty}
pts[#pts+1]={x,y}
end
return pts
end
return search(B) or search({}) or (amid and p1 or p2)-- {}: no furniture, only the screen edges
end
-- one straight walk along an iso axis (or both axes when the line is diagonal on the grid: it never is)
local function walkLine(v,x,y)
local dx,dy=x-v[2],y-v[3]
if math.abs(dx)<0.01 and math.abs(dy)<0.01 then return end
local a=(dx/2-dy)/2
local b=(dx/2+dy)/2
if math.abs(a)>0.01 then leg(v,a>0 and 0 or 1,math.abs(a)) end
if math.abs(b)>0.01 then leg(v,b>0 and 3 or 2,math.abs(b)) end
end
-- 유비 walks to x,y by koTownRoute: around the furniture of the picture, turning nearer the middle
local function walkTo(x,y)
local v=row(ME())
if not v then return end
local pts=koTownRoute(JY.SubScene,v[2],v[3],x,y)
for i=2,#pts do walkLine(v,pts[i][1],pts[i][2]) v[2],v[3]=pts[i][1],pts[i][2] end
v[2],v[3]=x,y
v[5]=0
frame()
end

local function hoverPerson()
if not MOUSE.IN(16,16,656,416) then return nil end
for _,v in ipairs(JY.Smap) do
if v[1]~=ME() then
local px,py=27+18*v[2],19+18*v[3]-32
if MOUSE.IN(px-20,py-28,px+20,py+28) then return v end
end
end
end

local function speak(v)
-- stand beside him on the side nearest to 유비, then face each other
local me=row(ME())
local best,bd
for d=0,3 do
local x,y=v[2]+CC.DX[d],v[3]+CC.DY[d]
local dist=(x-me[2])^2+(y-me[3])^2
if not bd or dist<bd then best,bd=d,dist end
end
local at=T.talkAt and T.talkAt[v[1]]
if at then-- someone behind a counter: 유비 stops in front of it, he keeps facing 유비's side
walkTo(at[1],at[2])
me[4]=at[3]
else
walkTo(v[2]+CC.DX[best],v[3]+CC.DY[best])
me[4]=KT.OPP[best]
v[4]=best
end
frame()
local nm=T.nick[v[1]]
local old
if nm then old=JY.Person[v[1]][NAME] JY.Person[v[1]][NAME]=nm end
talk(v[1],T.lines[v[1]])-- the click that closes it is swallowed by getkey (no koMouseReset here, it would let it through)
hear(T.bit and T.bit[v[1]])
local sid=T.shop and T.shop[v[1]]
if sid and talkYesNo(v[1],"\131\065\129\119\129\083 \131\115\130\086\134\121\129\075\129\076\129\089?") then DrawSMap() local sp=townSpecial(T.town) if sp then townSpecialShop(sp) else townShopOpen(townShop(T.town),true) end end
local act=T.act and T.act[v[1]]
if act=="hire" then
if not CC.Enhancement then talk(v[1],"\130\067\131\103\131\098 \133\073\129\088 \130\114\134\118\129\071 \130\097\129\109.")
else innKeeper(v[1],T.town) end-- (10-07: 묻는 창을 지우고 나서)
elseif act=="drink" then
if CC.Enhancement then talk(v[1],rumourLine(T.town)) end-- the tavern generals' whereabouts (they move after every battle)
if talkYesNo(v[1],"\129\111 \130\114\129\095\143\093 \130\087\135\121\129\110 \130\080\131\079\129\077 \137\113\133\102 \136\096\133\101\130\067\130\098 \139\074\129\071 \130\067\130\098 \134\069\129\090. \130\083\139\099\129\109?") then DrawSMap() koDrinkCity() end
elseif act=="talent" then-- kdef 447/448's meeting; from his name on he is himself
local pid=v[1]
if nm then
JY.Person[pid][NAME]=old nm=nil
talk(1,"\134\079\137\072\129\083 \129\098\140\113\130\083\129\068 \132\067\134\121\129\109?",
pid,"\133\102 \136\124\129\104\129\076\129\089? \133\102\130\098 "..JY.Person[pid][NAME].."(\129\071)\130\102 \129\087\129\076\129\077. \131\091\133\101\130\086\130\098 \135\076\131\098?",
1,"\131\118\130\098 \130\071\130\080\130\102 \129\097\129\091.",
pid,"\129\091, \135\105\131\078\129\071 \131\085\132\083 \130\071\130\080\138\105\129\071\130\086\130\084\129\090. \131\091\139\064 \132\123\129\068 \130\090\130\106\131\100 \129\078\139\126\129\080\129\075\129\076\129\077. \133\102, \130\071\130\080\138\105. \131\107\134\118\132\067\130\067\132\086 \129\111 \136\124\138\091 \129\098\142\118\134\121\129\075\129\076\129\077. \129\100\129\094 \130\094\129\097\129\094 \138\125 \129\113 \132\079\134\121\129\075\129\076\129\089? \133\102\129\068 \140\118\133\088\133\121 \132\080\130\090\130\098 \132\079\129\075\129\076\129\077.")
else talk(pid,"\129\100\129\094 \135\105\131\078\131\080 \130\094\129\097\129\094 \138\125 \129\113 \132\079\134\121\129\075\129\076\129\089?") end
if WarDrawStrBoxYesNo("\129\073\131\097 "..JY.Person[pid][NAME].."\129\083(\130\104) \130\094\129\097\132\083 \129\124\129\083\129\089\129\090?",M_White,true) then
talk(pid,"\129\091, \131\091\138\081\129\077\129\065 \135\078\130\114\129\087\129\076\129\077. \139\073\131\109\132\083 \138\085 \130\094\133\097\133\119\132\116\129\076\129\077.")
ModifyForce(pid,1)
if koStoryMarkTavernHire then koStoryMarkTavernHire(pid) end
PlayWavE(11)
DrawStrBoxCenter(JY.Person[pid][NAME].."\129\071(\129\094) \130\094\129\097\129\094 \132\067\132\107\129\077!")
-- he leaves the 주점 (the next one, if any, sits there next time)
for i,r in ipairs(JY.Smap) do if r[1]==pid then table.remove(JY.Smap,i) break end end
DrawSMap()
else
talk(pid,"\131\091\138\081\129\075\129\076\129\089? \161\173\161\173 \129\096\130\069\129\071 \136\071\130\102\130\067\130\086\129\065 \135\079 \131\082\133\101 \130\075\135\073\130\086\129\091. \133\102\130\098 \135\105\135\076\133\121 \129\098\131\071 \132\079\134\121\129\075\129\076\129\077.")
T.nick[pid]=nil T.lines[pid]="\129\110, \130\071\130\080\138\105. \135\079 \139\112\130\098\130\084\129\090."-- he has told his name
end
end
if nm then JY.Person[v[1]][NAME]=old end-- (kept through the questions: they show his name too)
end

---------------------------------------------------------------- region map
KT.CELL=40
KT.SMALL_FIG=false
function koTownFigReset() KT.SMALL_FIG=false end-- 5.0 (10-12): newgen redraws smap, the small town figures reload
KT.FIG_PCT=80-- 유비 on the region map, % of the scene figure
local function RG() return T.chap.region end
local function placeAt(cx,cy)
for _,p in ipairs(RG().places) do if p[2]==cx and p[3]==cy then return p end end
end
local function road(cx,cy)
local r=RG().road[cy+1]
return r~=nil and string.sub(r,cx+1,cx+1)=="."
end
local function canGo(name)
local f=rawget(_G,"koWujeNativeTownKnown") if f and rawget(_G,"koWujeCampaignActive") and koWujeCampaignActive() then return f(name) end
if name==T.home then return true end
if T.chap.link then-- 삼형제 외전: 지나온 외전 마을끼리만 (link[머무는 마을] = 갈 수 있는 마을들)
for _,t in ipairs(T.chap.link[T.home] or {}) do if t==name then return true end end
return false
end
-- open = {from[,to]} or a list of such windows (kdef event numbers)
local w=RG().open[name]
if w==nil or T.chap.towns[name]==nil then return false end
if type(w[1])~="table" then w={w} end
for _,r in ipairs(w) do if r[1]<=JY.EventID and JY.EventID<=(r[2] or 99999) then return true end end
return false
end
-- for test scripts: can 유비 walk to town name of chapter key c at event ev (home = the story town)
function koTownCanGo(c,home,name,ev)
local oT,oE=T,JY.EventID
T={chap=DATA[c],home=home} JY.EventID=ev
local r=canGo(name)
T,JY.EventID=oT,oE
return r
end
local function camFollow()
local Q=T.R
local mw,mh=RG().w*KT.CELL,RG().h*KT.CELL
Q.camx=math.max(0,math.min(mw-640,Q.px-320))
Q.camy=math.max(0,math.min(mh-400,Q.py-200))
end
local function regionDir(dx,dy)
if dy<0 then return dx>0 and 0 or 2 elseif dy>0 then return dx<0 and 1 or 3 end
return dx>0 and 3 or 1
end
-- 10-13 (사용자 "\130\067\129\068\129\102 \137\066\129\110\129\094\131\071 \132\071\131\098\134\069"): the story town (where this walk began) is flagged on the map, and a 돌아가기
-- button at the map's top-left walks 유비 back there along the roads and ends the walk (back in that town's scene)
local HB={label="\137\066\129\110\129\094\131\071"}-- one main-chunk local (the chunk is at its 200)
function HB.place() for _,q in ipairs(RG().places) do if q[1]==T.home then return q end end end
function HB.btn() return 24,24,24+#HB.label*8+16,42 end-- the battle top bar's button size (18 high)
function HB.box(x1,y1,x2,y2,a,c)
koRecordClassicFrame(x1,y1,x2-x1,y2-y1)
end
-- 10-13 (user): name tags (as the story town's, white text in the classic frame) under the places 유비 can use now: the
-- story town, the towns he may enter and the fields with a battle to replay. HB.fields = fieldBattles (defined further down)
function HB.tag(p)
local Q=T.R
local w=#p[1]*8+24
local x1=math.floor(16+p[2]*KT.CELL+KT.CELL/2-Q.camx-w/2)
local y1=math.floor(16+(p[3]+1)*KT.CELL-Q.camy+2)
if x1>=16 and x1+w<=656 and y1>=16 and y1+28<=416 then
HB.box(x1,y1,x1+w,y1+28,110,C_Name)
DrawString(x1+12,y1+6,p[1],M_White,16)
end
end
function HB.draw()
for _,p in ipairs(RG().places) do
if p[1]==T.home or ((p[4]==3 or p[4]==4) and canGo(p[1])) or ((p[4]==0 or p[4]==2 or KT.CAMP) and HB.fields and #HB.fields(p[1])>0) then HB.tag(p) end
end
local x1,y1,x2,y2=HB.btn()
koBarButton(x1,y1,x2,y2,HB.label)-- 10-13 (user): the battle top bar's button, no hover label
end
local function drawRegion()
local Q=T.R
lib.FillColor(0,0,0,0,0)
lib.SetClip(16,16,656,416)
lib.PicLoadCache(5,RG().pic*2,16-Q.camx,16-Q.camy,1)
local sx,sy=16+Q.px-Q.camx,16+Q.py-Q.camy+8
local rowi=({[0]=0,1,0,2,0})[Q.anim] or 0
local pic=(200+JY.Person[ME()][FIG]*4+Q.dir)*2
-- 유비 at 70% (the scene figure is too big for the map): smap opened a second time scaled into cache 13; a frame is 48x64 -> 34x45
if not KT.SMALL_FIG then lib.PicLoadFile(CC.SMAPPicFile[1],CC.SMAPPicFile[2],13,KT.FIG_PCT) KT.SMALL_FIG=true end
local fw,fh=math.floor(48*KT.FIG_PCT/100+0.5),64*KT.FIG_PCT/100
local hw=math.floor(fw/2)
sy=sy-2
if sx+hw>16 and sx-hw<656 and sy>16 and sy-fh<416 then-- off the view: not drawn (a clip with no area is ignored by the engine)
lib.SetClip(math.max(16,sx-hw),math.max(16,sy-math.floor(fh)),math.min(656,sx+hw),math.min(416,sy))
lib.PicLoadCache(13,pic,sx-hw,sy-math.floor(fh)-math.floor(rowi*fh+0.5),1)
end
lib.SetClip(0,0,0,0)
lib.PicLoadCache(4,201*2,0,0,1)
DrawGameStatus()
HB.draw()
if Q.hover then
lib.SetClip(336,434,494,458)
DrawString(336,440,Q.hover[1],M_White,16)
lib.SetClip()
end
end
-- the cells of the road from 유비's cell to (tx,ty), or nil
local function findPath(tx,ty)
local Q=T.R
local W,H=RG().w,RG().h
local sx,sy=Q.cx,Q.cy
local prev={}
local function key(x,y) return y*W+x end
local q,qi={{sx,sy}},1
prev[key(sx,sy)]=-1
while q[qi] do
local x,y=q[qi][1],q[qi][2]
qi=qi+1
if x==tx and y==ty then break end
for dy=-1,1 do for dx=-1,1 do
local nx,ny=x+dx,y+dy
if (dx~=0 or dy~=0) and nx>=0 and ny>=0 and nx<W and ny<H and prev[key(nx,ny)]==nil and (road(nx,ny) or (nx==tx and ny==ty)) then
prev[key(nx,ny)]=key(x,y)
q[#q+1]={nx,ny}
end
end end
end
if prev[key(tx,ty)]==nil then return nil end
local path={}
local k=key(tx,ty)
while k~=-1 do
table.insert(path,1,{k%W,math.floor(k/W)})
k=prev[k]
end
return path
end
local function regionWalk(path)
local Q=T.R
for i=2,#path do
local tx,ty=path[i][1]*KT.CELL+KT.CELL/2,path[i][2]*KT.CELL+KT.CELL/2
local dx,dy=tx-Q.px,ty-Q.py
Q.dir=regionDir(dx,dy)
local n=math.max(1,math.floor(math.max(math.abs(dx),math.abs(dy))/5))
for s=1,n do
Q.px=Q.px+dx/n Q.py=Q.py+dy/n
Q.anim=(Q.anim%4)+1
camFollow()
frame()
end
Q.px,Q.py=tx,ty
Q.cx,Q.cy=path[i][1],path[i][2]
end
Q.anim=0
frame()
end
local function enterTown(name)
T.town=name
JY.Base[LOC]=name
local d=streetDoor("out")
Dark()
build("street",d.x,d.y,KT.OPP[KT.ADIR[d.arrow]])
DrawSMap()
Light()
end
local function toRegion()
local p
for _,q in ipairs(RG().places) do if q[1]==T.town then p=q end end
T.mode="region"
T.R={cx=p[2],cy=p[3],px=p[2]*KT.CELL+KT.CELL/2,py=p[3]*KT.CELL+KT.CELL/2,dir=1,anim=0}
camFollow()
Dark()
DrawSMap()
Light()
end
local function askEnter(p)
PlayWavE(0)
if WarDrawStrBoxYesNo(p[1]..(p[4]==4 and "\129\102 \131\082\130\083\129\094\134\121\129\075\129\076\129\089?" or "\131\123\131\095\129\102 \131\082\130\083\129\094\134\121\129\075\129\076\129\089?"),M_White,true) then enterTown(p[1]) end
end
local function noWay()
PlayWavE(2)
WarDrawStrBoxConfirm("\131\091\135\069\131\109\139\109 \129\071\130\108\129\088 \129\113 \130\097\129\075\129\076\129\077.",M_White,true)
end
