-- 10-14 (제보: 신도성→거록 길로 갔는데 광천·청하가 다시 전투에 뜸): the story has forks (1장 신도성/광천 · 거록/청하, 태산·팽성·하구,
-- 2장 양양/강하, 3장 무릉·영릉·계양 · 가맹관/정군산/천탕산, 4장 신야/남군 ...), so "past the battle's event" is not "fought it".
-- A story battle (DefineWarMap outside a free battle) marks its koFreeData rows in the save's unused 战场特技 fields (0 in
-- newgame, so a new cycle starts clean); 战场特技0 = the event the marking began at. Battles from before that (saves made before
-- this fix) fall back on the fork's flag / joined general where there is one, else the old rule.
HB.MK="\213\189\179\161\204\216\188\188"-- 战场特技
-- 6.0 (11-03, 다시 전투 이야기판): a story's own replays = script/camp/<id>/replay_camp.lua (dev tool 캠페인다시전투.py):
-- {koFreeData index, its map, the story event of the battle, the region-map place names it is offered at...}
if rawget(_G,"koCamp") and CONFIG.koCampScript then local ok,t=pcall(dofile,CONFIG.koCampScript.."replay_camp.lua") if ok and type(t)=="table" then KT.CAMP=t end end
function HB.fought(b)
if (JY.Base[HB.MK..b[1]] or 0)>0 then return true end
if not (b[3]<JY.EventID) then return false end
if rawget(_G,"koCamp") then local m0=JY.Base[HB.MK.."0"] or 0 return not (m0>0 and b[3]>=m0) end-- 6.0 story (11-03)
if b[1]==15 then return GetFlag(1014) end-- 10-16: 팽성II / 하구II (1012 / 1014 = set on turn 2 of that battle)
if HB.HAGU2 and b[1]==HB.HAGU2 then return GetFlag(1012) end
local m0=JY.Base[HB.MK.."0"] or 0
if m0>0 and b[3]>=m0 then return false end
local function ours(p) return JY.Person[p]~=nil and JY.Person[p]["\190\253\214\247"]==1 end
local i=b[1]
if i==4 then return not (ours(221) and not ours(245)) end-- 광천: 신도성 길이면 번궁, 광천 길이면 한영이 합류
if i==5 then return not GetFlag(133) end-- 청하 / 거록 (133 = 거록 길)
if i==6 then return GetFlag(133) end
if i==11 then return GetFlag(8) end-- 태산·팽성·하구: 소탕 플래그
if i==12 then return GetFlag(9) end
if i==13 then return GetFlag(10) end
if i==52 then return GetFlag(92) end-- 신야II / 남군 (92 = 신야 길)
if i==53 then return not GetFlag(92) end
return true
end
do
local dw=DefineWarMap
function DefineWarMap(id,name,a,b,c,...)
if c~=-1 and not (CC.koFree or CC.koReplay) and JY.Base~=nil then
local fd=rawget(_G,"koFreeData")
for i,d in ipairs(fd or {}) do
if d.name==name and d.map==id then
if (JY.Base[HB.MK.."0"] or 0)==0 then JY.Base[HB.MK.."0"]=math.max(1,JY.EventID or 1) end
JY.Base[HB.MK..i]=1
end
end
end
return dw(id,name,a,b,c,...)
end
end
-- 6.0 (11-03): the story battles that can be replayed at a place of the region map now (KT.CAMP rows {i,map,ev,place...})
function HB.campAt(name)
local fd,r=rawget(_G,"koFreeData"),{}
if not (KT.CAMP and fd and rawget(_G,"koFreeStart")) then return r end
for _,b in ipairs(KT.CAMP) do
local at=false for k=4,#b do if b[k]==name then at=true end end
if at and fd[b[1]] and fd[b[1]].map==b[2] and HB.fought(b) then r[#r+1]=b[1] end
end
return r
end
function koCampReplayAt(name) return HB.campAt(name) end-- (the story town walk, campaign/town.lua)
-- enter the town (go: it may be entered) or replay one of the battles bs: 0 = enter, a koFreeData index, nil = nothing
function HB.ask(name,go,bs)
local pick=bs[1]
if go or #bs>1 then
local m,act={},{}
if go then m[1]={fillblank(name.." \131\082\130\083\129\094\131\071",20),nil,1} act[1]=0 end
for _,id in ipairs(bs) do m[#m+1]={fillblank(koFreeData[id].name,20),nil,1} act[#act+1]=id end
DrawYJZBox2(-1,40,go and "\129\073\135\074\129\083 \129\097\130\086\134\121\129\075\129\076\129\089?" or "\130\083\134\115 \130\066\132\101\130\104 \129\077\130\086 \129\097\134\121\129\075\129\076\129\089?",M_White)
local s=ShowMenu(m,#m,0,0,0,0,0,4,1,16,M_White,M_White)
if s<=0 then return nil end
pick=act[s]
if pick==0 then return 0 end
end
PlayWavE(0)
local max=rawget(_G,"koFreeExpMax") or 3
local used=(rawget(_G,"koFreeExpUsed") and koFreeExpUsed()) or 0
if used>=max then WarDrawStrBoxConfirm("\129\071\130\087 \131\097\129\102\131\087 \129\077\130\086 \137\106\133\091 \129\113 \132\079\130\098 "..max.."\130\087\129\083 \130\090\130\091 \144\100\129\075\129\076\129\077.",M_White,true) return nil end
if WarDrawStrBoxYesNo(koFreeData[pick].name.."\130\104 \129\077\130\086 \129\097\134\121\129\075\129\076\129\089?*(\129\071 \131\097\129\102\131\087 "..(max-used).."\130\087 \132\108 \129\088 \129\113 \132\079\129\075\129\076\129\077)",M_White,true) then return pick end
return nil
end
function koCampReplayAsk(name,go) local bs=HB.campAt(name) if #bs==0 then return nil end return HB.ask(name,go,bs) end
-- the battles that can be replayed at a field now
local function fieldBattles(name)
if rawget(_G,"koWujeCampaignActive") and koWujeCampaignActive() then return HB.campAt(name) end
local fd=rawget(_G,"koFreeData")
if not fd or not rawget(_G,"koFreeStart") then return {} end
local f=KT.FIELD[T.chap.key] and KT.FIELD[T.chap.key][name]
local r={}
for _,b in ipairs(f or {}) do
if fd[b[1]] and fd[b[1]].map==b[2] and HB.fought(b) then r[#r+1]=b[1] end
end
return r
end
HB.fields=fieldBattles
-- 6.0 (11-03): a story town (or village) where a battle was fought: walk there, then enter it or replay
function HB.townPick(p,bs)
local Q=T.R
if p[2]~=Q.cx or p[3]~=Q.cy then
local path=findPath(p[2],p[3])
if not path then noWay() return end
regionWalk(path)
end
local r=HB.ask(p[1],canGo(p[1]),bs)
if r==0 then askEnter(p) elseif r then T.battle=r return "battle" end
end
local function regionClick(p)
local Q=T.R
if (p[4]==3 or p[4]==4) and KT.CAMP then local bs=fieldBattles(p[1]) if #bs>0 then return HB.townPick(p,bs) end end
if p[4]==0 or p[4]==2 then
local bs=fieldBattles(p[1])
if #bs==0 then noWay() return end
if p[2]~=Q.cx or p[3]~=Q.cy then
local path=findPath(p[2],p[3])
if not path then noWay() return end
regionWalk(path)
end
local pick=bs[1]
if #bs>1 then
local m={}
for i,id in ipairs(bs) do m[i]={fillblank(koFreeData[id].name,20),nil,1} end
DrawYJZBox2(-1,40,"\130\083\134\115 \130\066\132\101\130\104 \129\077\130\086 \129\097\134\121\129\075\129\076\129\089?",M_White)
local s=ShowMenu(m,#m,0,0,0,0,0,4,1,16,M_White,M_White)
if s<=0 then return end
pick=bs[s]
end
PlayWavE(0)
if (rawget(_G,"koFreeExpUsed") and (rawget(_G,"koFreeExpUsed") and koFreeExpUsed()) or 0)>=(rawget(_G,"koFreeExpMax") or 3) then
WarDrawStrBoxConfirm("\129\071\130\087 \131\097\129\102\131\087 \129\077\130\086 \137\106\133\091 \129\113 \132\079\130\098 "..(rawget(_G,"koFreeExpMax") or 3).."\130\087\129\083 \130\090\130\091 \144\100\129\075\129\076\129\077.",M_White,true)
return
end
if WarDrawStrBoxYesNo(koFreeData[pick].name.."\130\104 \129\077\130\086 \129\097\134\121\129\075\129\076\129\089?*(\129\071 \131\097\129\102\131\087 "..((rawget(_G,"koFreeExpMax") or 3)-koFreeExpUsed()).."\130\087 \132\108 \129\088 \129\113 \132\079\129\075\129\076\129\077)",M_White,true) then
T.battle=pick
return "battle"
end
return
end
if (p[4]~=3 and p[4]~=4) or not canGo(p[1]) then noWay() return end
if p[2]~=Q.cx or p[3]~=Q.cy then
local path=findPath(p[2],p[3])
if not path then noWay() return end
regionWalk(path)
end
askEnter(p)
end
function HB.go()
local Q=T.R
PlayWavE(0)
if not WarDrawStrBoxYesNo(T.home.." \130\125\131\080\131\097\131\109\132\083 \137\066\129\110\129\094\134\121\129\075\129\076\129\089?",M_White,true) then return end
local hp=HB.place()
if hp and (hp[2]~=Q.cx or hp[3]~=Q.cy) then
local path=findPath(hp[2],hp[3])
if path then regionWalk(path) end
end
return "home"
end
local function regionStep(e,k)
local Q=T.R
Q.hover=nil
local onBtn=MOUSE.IN(HB.btn())
local mw,mh=RG().w*KT.CELL,RG().h*KT.CELL
local mx,my=MOUSE.x,MOUSE.y
if MOUSE.IN(16,16,656,416) and not onBtn then
Q.hover=placeAt(math.floor((mx-16+Q.camx)/KT.CELL),math.floor((my-16+Q.camy)/KT.CELL))
-- the map scrolls while the mouse rests on its border
if mx<40 then Q.camx=Q.camx-12 elseif mx>632 then Q.camx=Q.camx+12 end
if my<40 then Q.camy=Q.camy-12 elseif my>392 then Q.camy=Q.camy+12 end
end
if e==1 then
if k==VK_LEFT then Q.camx=Q.camx-40 elseif k==VK_RIGHT then Q.camx=Q.camx+40
elseif k==VK_UP then Q.camy=Q.camy-40 elseif k==VK_DOWN then Q.camy=Q.camy+40 end
end
Q.camx=math.max(0,math.min(mw-640,Q.camx))
Q.camy=math.max(0,math.min(mh-400,Q.camy))
if onBtn and MOUSE.CLICK(HB.btn()) then return HB.go() end
if (e==1 and k==27) or MOUSE.ESC() then
local p=placeAt(Q.cx,Q.cy)
if p and (p[4]==3 or p[4]==4) then askEnter(p) end
elseif Q.hover and MOUSE.CLICK(16,16,656,416) then
return regionClick(Q.hover)
end
end

---------------------------------------------------------------- streets and rooms
-- walk to a street door: true = back to the story scene
local function useDoor(d)
walkTo(d.x,d.y)
if d.to=="story" then
row(ME())[4]=d.arrow and KT.ADIR[d.arrow] or 0
frame()
if T.town==T.home then return true end
PlayWavE(2)
WarDrawStrBoxConfirm("\130\067\131\103\131\098 \129\071\135\069 \130\125\131\080\131\097\129\102 \133\082\133\073\129\071 \130\097\129\075\129\076\129\077.",M_White,true)
return false
end
if d.to=="out" then
row(ME())[4]=KT.ADIR[d.arrow]
frame()
if T.chap.link and #(T.chap.link[T.home] or {})==0 then PlayWavE(2) WarDrawStrBoxConfirm("\130\067\131\103\131\098 \129\071 \131\123\129\083 \139\088\131\083 \129\113 \130\097\129\075\129\076\129\077.",M_White,true) return false end-- 삼형제 외전: 갈 곳이 없는 마을
PlayWavE(0)
if WarDrawStrBoxYesNo("\133\088\129\083 \139\119\131\109\132\083 \131\118\129\094\134\121\129\075\129\076\129\089?",M_White,true) then toRegion() end
return false
end
row(ME())[4]=d.arrow and KT.ADIR[d.arrow] or 0
frame()
PlayWavE(0)
if not d.arrow and not WarDrawStrBoxYesNo(d.label.."\129\102 \131\082\130\083\129\094\134\121\129\075\129\076\129\089?",M_White,true) then return false end
T.door=d
local E=KT.ROOM[d.to].exit
Dark()
build(d.to,E[1],E[2],KT.OPP[KT.ADIR[E[3]]])
DrawSMap()
Light()
return false
end
local function leaveRoom()
local E=KT.ROOM[T.cur].exit
walkTo(E[1],E[2])
row(ME())[4]=KT.ADIR[E[3]]
frame()
local d=T.door
Dark()
build("street",d.x,d.y,1)
DrawSMap()
Light()
end

local function hint(x1,y1,s)
koRecordClassicFrame(x1+10,y1-30,#s*8+24,28)
DrawString(x1+22,y1-24,s,M_White,16)
end
local function sign(d,on)
local x,y,w,h=tagRect(d)
koRecordClassicFrame(x,y,w,h)
DrawString(x+12,y+6,d.label,M_White,16)
end
local function drawTags()
if T.cur~="street" then
local RM=KT.ROOM[T.cur]
local E=RM.exit

local x1,y1,x2,y2=arrowRect(E[1],E[2])
if MOUSE.IN(x1,y1,x2,y2) then hint(x1,y1,RM.hall and "\134\069\129\117\132\083" or "\131\118\129\094\131\071") end-- inside a building (주점): 나가기; 궁궐 앞 is outdoors
if RM.hall then sign(RM.hall,overDoor(RM.hall,MOUSE.IN)) end
return
end
for _,d in ipairs(townData().street.doors) do
local on=overDoor(d,MOUSE.IN)
if d.arrow then

if on then local x1,y1=arrowRect(d.x,d.y) hint(x1,y1,d.label) end
else
sign(d,on)
end
end
end

local talking=0-- story or town dialogue on screen: no story arrow behind it
local function quiet(fn) return function(...) talking=talking+1 local r=fn(...) talking=talking-1 return r end end-- talk returns nothing, talkYesNo one value
talk=quiet(talk)
talkYesNo=quiet(talkYesNo)
local function storyArrow()-- the story scene's arrow: x,y,arrow
local f=rawget(_G,"koWujeHallExit") if f and rawget(_G,"koWujeCampaignActive") and koWujeCampaignActive() then local p=f(JY.SubScene) if p then return p end end
return STORY[JY.SubScene] or KT.STORY_DEF
end
function koTownStory() return storyArrow() end-- for test scripts
-- 10-13 (user: the map background before a scene change or a battle showed the arrow): an event started from the free-action screen
-- (a person clicked: sortie, a scene change) runs with JY.Status still GAME_SMAP_MANUAL, so its map background got the
-- story arrow. HB.ev = DoEvent depth (kept in HB: the main chunk is at its 200 locals); the arrow only at depth 0.
HB.ev=0
local oldDoEvent=DoEvent
function DoEvent(...)
HB.ev=HB.ev+1
local r=table.pack(pcall(oldDoEvent,...))
HB.ev=HB.ev-1
if not r[1] then error(r[2],0) end
return table.unpack(r,2,r.n)
end
local oldDrawSMap=DrawSMap
function DrawSMap()
if CC.koTownBattle and JY.Status~=GAME_WMAP then-- a replayed battle being set up: never the city scene behind it
local s,m=JY.SubScene,JY.Smap
JY.SubScene,JY.Smap=-1,{}
oldDrawSMap()
JY.SubScene,JY.Smap=s,m
return
end
if T and T.mode=="region" then drawRegion() return end
oldDrawSMap()
if T then
if talking==0 then drawTags() end
elseif avail() and talking==0 and HB.ev==0 then
local s=storyArrow()
local fx,fy=feet(s[1],s[2])
lib.PicLoadCache(5,KT.ARROW[s[3]]*2,fx-48,fy-28,1)
local x1,y1=arrowRect(s[1],s[2])
local x2,y2=fx+44,fy+26
if MOUSE.IN(x1,y1,x2,y2) then hint(x1,y1,"\131\118\129\094\131\071") end
end
end

local function sceneStep(e,k,hp)
if (e==1 and k==27) or MOUSE.ESC() then
PlayWavE(1)
if T.cur~="street" then leaveRoom() end
elseif hp and MOUSE.CLICK(27+18*hp[2]-20,19+18*hp[3]-60,27+18*hp[2]+20,19+18*hp[3]-4) then
JY.Tid=0
speak(hp)
elseif T.cur=="street" then
for _,d in ipairs(townData().street.doors) do
if overDoor(d,MOUSE.CLICK) then
return useDoor(d)
end
end
else
local RM=KT.ROOM[T.cur]
local E=RM.exit
local x1,y1,x2,y2=arrowRect(E[1],E[2])
if MOUSE.CLICK(x1,y1,x2,y2) then
PlayWavE(0)
leaveRoom()
elseif RM.hall and overDoor(RM.hall,MOUSE.CLICK) then
walkTo(RM.hall.x,RM.hall.y)
row(ME())[4]=0
frame()
if T.town==T.home then return true end
PlayWavE(2)
WarDrawStrBoxConfirm("\130\067\131\103\131\098 \129\071\135\069 \130\125\131\080\131\097\129\102 \133\082\133\073\129\071 \130\097\129\075\129\076\129\077.",M_White,true)
end
end
end

local function loop()
while true do
JY.ReFreshTime=lib.GetTime()
JY.Tid=0
local hp=T.mode=="scene" and hoverPerson() or nil
if hp then JY.Tid=hp[1] end
DrawSMap()
if MOUSE.HOLD(673,321,710,366) then lib.PicLoadCache(4,220*2,673,321,1)
elseif MOUSE.HOLD(713,321,750,366) then lib.PicLoadCache(4,221*2,713,321,1)
elseif MOUSE.HOLD(673,369,710,414) then lib.PicLoadCache(4,222*2,673,369,1)
elseif MOUSE.HOLD(713,369,750,414) then lib.PicLoadCache(4,223*2,713,369,1) end
ShowScreen()
local e,k=koPollKey()
if e==0 or MOUSE.EXIT() then koExit() end
if MOUSE.CLICK(673,321,710,366) then
PlayWavE(0)
if not CC.Enhancement then WarDrawStrBoxConfirm("\130\067\131\103\131\098 \133\125\132\111\129\088 \129\073\131\097\129\071 \130\097\129\075\129\076\129\077.",M_White,true)
elseif T.cur=="inn" then tavernHire(T.town)-- in the 주점: its own list
else WarDrawStrBoxConfirm(townData().inn and "\131\072\134\076 \129\073\131\097\131\098 \129\071 \133\088\129\083 \130\075\135\070\129\102\131\087 \132\086\131\083 \129\113 \132\079\129\075\129\076\129\077.*\130\075\135\070 \130\075\129\106\129\102\129\081 \136\124\129\083 \130\064\130\083 \131\115\131\111\129\090." or "\129\071 \133\088\129\083\129\102\130\098 \130\075\135\070\129\071 \130\097\129\075\129\076\129\077.",M_White,true) end
elseif MOUSE.CLICK(713,321,750,366) then
PlayWavE(0)
Person_Menu()
elseif MOUSE.CLICK(673,369,710,414) then
local sid=townShop(T.town)-- the town 유비 is in, not the story's
if sid>0 then townShopOpen(sid) else PlayWavE(2) WarDrawStrBoxConfirm("\129\071 \133\088\129\083\129\102\130\098 \129\068\130\119\129\067\129\071 \130\097\129\075\129\076\129\077.",M_White,true) end
elseif MOUSE.CLICK(713,369,750,414) then
PlayWavE(2)
WarDrawStrBoxConfirm("\133\102\131\097\129\123 \129\069\129\070\131\098 \130\125\131\080\131\097\129\102\131\087 \129\088 \129\113 \132\079\129\075\129\076\129\077.",M_White,true)
elseif T.mode=="region" then
local r=regionStep(e,k)
if r=="battle" or r=="home" then return end-- 10-13: "home" = the 돌아가기 button
if MOUSE.status=="CLICK" then MOUSE.status="IDLE" end
else
hp=hoverPerson()-- where the mouse is now (a quick click may come without a hover frame)
if sceneStep(e,k,hp) then return end
end
if MOUSE.status=="CLICK" then MOUSE.status="IDLE" end-- a click nothing took (the floor) is dropped, not kept for the next person under the mouse
end
end

local townBattleStart,townBattleBack-- (below)
function koTownVisit()
local td,town,c=koTownData()
if not td then return end
local oldScene,oldSmap,oldLoc=JY.SubScene,JY.Smap,JY.Base[LOC]
-- 유비 walks onto the story scene's arrow first (put back where he stood on return)
local s=storyArrow()
local me=row(ME())
local mx,my,md
if me then mx,my,md=me[2],me[3],me[4] walkTo(s[1],s[2]) me[4]=KT.ADIR[s[3]] frame() end
T={chap=c,home=town,town=town}
Dark()
if td.palace then
T.door=streetDoor("palace")
local H=KT.ROOM.palace.hall
build("palace",H.x,H.y,1)
else
local home=streetDoor("story")
build("street",home.x,home.y,home.arrow and KT.OPP[KT.ADIR[home.arrow]] or 1)
end
DrawSMap()
Light()
if HB.startAt then local n=HB.startAt HB.startAt=nil local d T.town=n JY.Base[LOC]=n d=streetDoor("inn") or streetDoor("out") Dark() build("street",d.x,d.y,1) DrawSMap() Light() end
local ok,err=pcall(loop)
local battle=T and T.battle
T=nil
JY.SubScene,JY.Smap,JY.Tid=oldScene,oldSmap,0
JY.Base[LOC]=oldLoc
if me then me[2],me[3],me[4],me[5]=mx,my,md,0 end
if not ok then error(err,0) end
if battle then if rawget(_G,"koCamp") then HB.defer=battle else townBattleStart(battle) end return end
Dark()
DrawSMap()
Light()
end
-- a replayed battle: the city as it is now goes to its own slot, the free addon fights it as a 원정 from that slot (the result
-- — experience, items, gold — written back onto it, at most koFreeExpMax a chapter), and when the battle ends (won, lost or
-- given up: the game falls back to the title) that slot is loaded again: back in this city phase.
KT.BATTLE_SLOT=17-- (16 is the rewind addon's rewind.sav: sharing it lost the city when rewind dropped its slot at war_end — QA 2026-10-03)
