function HB.fixTeam(team)
local fx=HB.pend and HB.FIX[HB.pend]
if not fx or type(team)~="table" then return end
for _,e in ipairs(fx) do
local p=JY.Person[e[1]]
-- 10-16: 관우·장비 away from the army (1장 끝) are not put in; e[5] = the story's condition flag (SelectTerm 6th field: 공손찬 0, 도겸 1)
-- 10-17: a story ambusher (SelectTerm 7th field 1: 영천 관우·관평·주창, 박망파's six, ...) goes in hidden even when mine, so it
-- comes out when the story's script shows it; one that cannot go in leaves its tile (no free pick standing there from turn 1)
local hide=HB.FIXHIDE[HB.pend..":"..e[1]..":"..e[2]..":"..e[3]] and 1 or 0
local mine=p and p["\190\253\214\247"]==1
if p and ((hide==1 and mine) or (not mine and not ((e[1]==2 or e[1]==3) and HB.pend~=48))) then-- (맥 = 관우 is the battle itself: always in)
local put=false
for k=1,#team-6,7 do if team[k+1]==e[2] and team[k+2]==e[3] then team[k]=e[1]-1 if e[5] then team[k+5]=e[5] end team[k+6]=hide put=true break end end
if not put then local n=#team team[n+1]=e[1]-1 team[n+2]=e[2] team[n+3]=e[3] team[n+4]=e[4] team[n+5]=0 team[n+6]=e[5] or -1 team[n+7]=hide end
elseif hide==1 then
for k=1,#team-6,7 do if team[k]==-1 and team[k+1]==e[2] and team[k+2]==e[3] then for _=1,7 do table.remove(team,k) end break end end
end
end
end
do
local st=SelectTerm
function SelectTerm(fid,team,...)
HB.fixTeam(team)
return st(fid,team,...)
end
end
