-- 10-16 (제보: 사수관 보너스가 조건 없이 받아짐): bonus goals that read once-a-cycle story flags judged on this replay instead.
-- 271 = both hidden spots reached in this battle (177/178 stay set from the story so the items are not paid twice);
-- 239 = 공손찬(13)·도겸(16) really not in the battle
function HB.spotHit(ev)
local s=HB.storyOn() local b=s and koFreeData[JY.Base[HB.MK.."498"] or 0]
if not b then return false end
local v,j=JY.Base[HB.MK.."497"] or 0,0
for _,l in ipairs({b.items or {},b.golds or {}}) do for _,g in ipairs(l) do
if g[4]==ev then return math.floor(v/2^j)%2==1 end
j=j+1
end end
return false
end
function HB.spotTrack()
local b=koFreeData[JY.Base[HB.MK.."498"] or 0]
if not b then return end
local v,j=JY.Base[HB.MK.."497"] or 0,0
for _,l in ipairs({b.items or {},b.golds or {}}) do for _,g in ipairs(l) do
if math.floor(v/2^j)%2==0 and WarCheckLocation(-1,g[1],g[2]) then v=v+2^j end
j=j+1
end end
JY.Base[HB.MK.."497"]=v
end
HB.BONUSNEED={[271]=function() return HB.spotHit(177) and HB.spotHit(178) end,
[239]=function() return GetWarID(13)==0 and GetWarID(16)==0 end}
function HB.storyArm(idx)
local s=HB.SCR[idx]
if not s or not Event[s[1]] then return end
for _,fl in ipairs(s[3]) do JY.Base["\202\194\188\254"..fl]=0 end
JY.Base[HB.MK.."498"]=idx
JY.Base[HB.MK.."499"]=s[1]
JY.Base[HB.MK.."497"]=0-- spots reached in this replay (HB.spotTrack)
War.WarTarget=s[4]
War.koBonusText=nil
end
function HB.storyOn()
local p=JY.Base and (JY.Base[HB.MK.."499"] or 0) or 0
return p>0 and HB.SCR[JY.Base[HB.MK.."498"] or 0] or nil
end
-- one call of the story's war event (and once more after NextEvent, as WarCheckStatus does), with the story's victory money /
-- experience muted. false: the script stopped (ended the battle or left its events)
function HB.storyStep(s)
local id=JY.Base[HB.MK.."499"]
local keep=JY.EventID
local gm,wge,b4,b8,dsb=GetMoney,WarGetExp,bonus_moneyexp_4,bonus_moneyexp_8,DrawStrBoxCenter
local kbd=rawget(_G,"koBonusDone")
if kbd then koBonusDone=function(fl,...) local need=HB.BONUSNEED[fl] if need and not need() then return false end return kbd(fl,...) end end
local hush=false
GetMoney=function(n) hush=true end-- the story's gold (victory money; its gold spots are paid by koFreeEvent below from the battle's spot list)
WarGetExp=function() end
bonus_moneyexp_4=function() end
bonus_moneyexp_8=function() if JY.Status==GAME_WMAP then return b8() end end
DrawStrBoxCenter=function(str,c) if hush then hush=false return end return dsb(str,c) end
local ok,err=pcall(function()
JY.EventID=id
Event[id]()
if JY.EventID~=id and (JY.Status==GAME_WMAP or JY.Status==GAME_WARWIN) and JY.EventID>=s[1] and JY.EventID<=s[2] and Event[JY.EventID] then
id=JY.EventID
Event[id]()
end
end)
GetMoney,WarGetExp,bonus_moneyexp_4,bonus_moneyexp_8,DrawStrBoxCenter=gm,wge,b4,b8,dsb
if kbd then koBonusDone=kbd end
local now=JY.EventID
JY.EventID=keep
if not ok then
lib.Debug("town replay script "..tostring(id)..": "..tostring(err))
JY.Base[HB.MK.."499"]=0
return false
end
-- the story leaving the battle = won (to the city; GAME_WMAP2 = straight on to the next battle: 장판파I, 와구관I, 업I·II);
-- GAME_START (업II's last turn ends the game) = lost
if JY.Status==GAME_SMAP_AUTO or JY.Status==GAME_SMAP_MANUAL or JY.Status==GAME_WMAP2 then JY.Status=GAME_WARWIN JY.Base[HB.MK.."499"]=0 return false end
if JY.Status==GAME_START then JY.Status=GAME_WARLOSE JY.Base[HB.MK.."499"]=0 return false end
if now<s[1] or now>s[2] or not Event[now] then JY.Base[HB.MK.."499"]=0 return false end
JY.Base[HB.MK.."499"]=now
return true
end
do
local base=rawget(_G,"koFreeEvent") or function() end
function koFreeEvent()
local s=HB.storyOn()
if not s or not (JY.Status==GAME_WMAP or JY.Status==GAME_WARWIN) then return base() end
local f=CC.koFree
if not f then-- a save made in the battle, loaded: as the free addon does
local idx=JY.Base["\202\194\188\254".."1990"] or 0
if idx<1 or idx>#koFreeData then return base() end
f={idx=idx,started=true,exp=((JY.Base["\202\194\188\254".."1991"] or 0)>0),src=JY.Base["\202\194\188\254".."1991"] or 0}
CC.koFree=f
CC.koReplay=true
War.koBonusText=War.koBonusText or (rawget(_G,"koBonusPreT") and koBonusPreT[War.WarName or ""])
end
f.started=true-- the story's opening event shows the goals and plays the tune
local dead=(JY.Death or 0)>0
if JY.Status==GAME_WMAP then HB.spotTrack() end
if JY.Status==GAME_WMAP and not dead then-- the hidden gold spots, as the free addon pays them (once a cycle, on the story's flags)
for _,g in ipairs(koFreeData[f.idx].golds or {}) do
if (not GetFlag(g[4])) and WarCheckLocation(-1,g[1],g[2]) then GetMoney(g[3]) PlayWavE(11) DrawStrBoxCenter("\130\085\131\103 "..g[3].."\129\083 \131\067\131\068!") SetFlag(g[4],1) end
end
end
HB.storyStep(s)
if dead then return end
if JY.Status==GAME_WARWIN or JY.Status==GAME_WARLOSE then return base() end
if JY.Status~=GAME_WMAP then return end
if not HB.storyOn() then return base() end-- the script left off mid-battle: the free addon's own tick from here
local alive=0
for i=1,War.PersonNum do local v=War.Person[i] if (not v.enemy) and v.live then alive=alive+1 end end
if alive==0 then
JY.Status=GAME_WARLOSE
if koWar then koWar.lost=true end
f.lostmsg=true
koFreeLost(f)
PlayBGM(4)
WarDrawStrBoxWaitKey("\129\110\130\084\129\071 \130\066\134\085\129\080\129\077...",M_White)
end
end
if rawget(_G,"koFreeEID") then Event[koFreeEID]=koFreeEvent end-- (the free addon registered its own at load: a battle save resumes through ours)
end
townBattleBack=function()-- false: the city slot is gone (a save made during an old town battle, finished long ago): the title then
CC.koTownBattle=nil
CC.koFree=nil CC.koReplay=nil
if not fileexist(CC.R_GRPFilename[KT.BATTLE_SLOT]) then return false end
LoadRecord(KT.BATTLE_SLOT)
os.remove(CC.R_GRPFilename[KT.BATTLE_SLOT])
for i=1,JY.PersonNum-1 do GetPic(i) end
JY.Status=GAME_SMAP_MANUAL
Dark()
DrawSMap()
Light()
return true
end
-- the free addon loads the city slot to set the battle up: its story scene would show behind the deploy screen (the íìì¥
-- flashing between the region map and the battle): blank it for a town battle (the slot on disk keeps it)
koOn("free_prepare",function(b,opt,exp) if CC.koTownBattle then JY.SubScene=-1 JY.Smap={}
-- 10-16 (제보: 하구 동량 → 비위, 태산 이명 → 조식, 팽성 조하 → 사마의): the free addon swaps a story enemy who is now mine for a
-- random general (원정). A town replay keeps the story's enemy: he leaves my roster for this battle only (the city slot is
-- loaded back afterwards, and the result is written only onto those still mine)
if b and HB.pend and HB.ADD[HB.pend] and not b.koEnemy0 then local t={} for _,r in ipairs(b.enemy) do t[#t+1]=r end
for _,r in ipairs(HB.ADD[HB.pend]) do t[#t+1]=r end b.koEnemy0=b.enemy b.enemy=t end
if exp and b then for _,r in ipairs(b.enemy or {}) do local id=r[1]+1 local p=JY.Person[id]
if id>1 and p and not koFreeIsGeneric(id) and p["\190\253\214\247"]==1 then p["\190\253\214\247"]=0 end end end
end end)
-- the end of a replayed battle drops to the title: back to the city instead
local oldTitle=YJZMain_sub
function YJZMain_sub(...)
if CC.koTownBattle and townBattleBack() then return end
return oldTitle(...)
end
-- the free addon's win message names the save slot ("16"): for a town battle say what happened instead
local oldExpFinish=rawget(_G,"koFreeExpFinish")
if oldExpFinish then
function koFreeExpFinish(f)
if not CC.koTownBattle then return oldExpFinish(f) end
-- 10-16 (제보: 다시 전투로 이명·조하·동량을 다시 등용하면 레벨이 적장 레벨로): the story's named enemies left my roster for the
-- battle (free_prepare below) and the story's own persuasion took them back at the enemy row's level. Their city record (or
-- their absence from it) stays as it was: they are not in the army written back
do local b=koFreeData[f.idx] for _,r in ipairs((b and b.enemy) or {}) do local id=r[1]+1 local p=JY.Person[id]
if id>1 and p and not koFreeIsGeneric(id) then p["\190\253\214\247"]=0 end end end
-- free's boxes are held back: its success box (naming slot 16) gives way to ours, anything else (no exp.sav, the
-- chapter's limit used up, a failed save) is shown as free wrote it
local oc=WarDrawStrBoxConfirm
local boxes={}
WarDrawStrBoxConfirm=function(...) boxes[#boxes+1]=table.pack(...) end
local ok,err=pcall(oldExpFinish,f)
WarDrawStrBoxConfirm=oc
if not ok then error(err,0) end
local saved=false
for _,b in ipairs(boxes) do if type(b[1])=="string" and string.find(b[1],"\131\081\129\070 \131\115\129\067\129\083 \133\106\133\107",1,true) then saved=true end end
if not saved then
for _,b in ipairs(boxes) do oc(table.unpack(b,1,b.n)) end
return
end
local left=(rawget(_G,"koFreeExpMax") or 3)-((rawget(_G,"koFreeExpUsed") and koFreeExpUsed()) or 0)
WarDrawStrBoxConfirm("\130\066\132\101 \134\064\129\123(\131\064\133\085\132\081\161\164\129\068\130\119\161\164\131\103)\130\104 \133\065\129\126\129\080\129\075\129\076\129\077.*\129\071 \131\097\129\102\131\087 "..left.."\130\087 \132\108 \129\077\130\086 \137\106\133\091 \129\113 \132\079\129\075\129\076\129\077.",M_White,true)
end
end
-- which game a load leaves us in: a town battle only when the loaded record is one (a free battle, 事件1990, whose army
-- goes back to the town slot, 事件1991 = 17: also a save made during it, loaded later or in another session). Any
-- other record a player loads (a city save from the battle menu, ...) ends the town battle. The loads of the town /
-- free flow itself (0 new game, 15 exp.sav, 17 the town slot) leave it as it is.
local oldLoad=LoadRecord
function LoadRecord(id,...)
local r=table.pack(oldLoad(id,...))
HB.startAt=nil-- 10-13 test saves: a "<save>.town" file beside the record (a town name) = start in that town's street at the inn door
if id and id>0 and id<=10 and CC.R_GRPFilename[id] then local f=io.open((string.gsub(CC.R_GRPFilename[id],"%.sav$",".town")),"rb") if f then HB.startAt=f:read("*l") f:close() end end
-- 주점 무장's seed for a record that has none yet (a save from before 5.0's taverns, a new game): made from the loaded record
-- itself, so loading the same save again gives the same seed even before it is saved with one
if JY.Base and ev(EV_SEED)<=0 then
local h
if id==0 then h=os.time()%30011*7-- (QA: record 0 — a new game / new cycle — is the same for every player: the clock there)
else h=(koGold() or 0)%9973+(JY.EventID or 0)*31+(JY.Person[1] and JY.Person[1]["\181\200\188\182"] or 0)*977+ev(1999)*7 end
setev(EV_SEED,h%30000+1)
end
if id==16 then beatenWar={} end-- (QA: a rewound turn rolls the 격파 +5 back with the event slots: it may be earned again)
if id~=0 and id~=15 and id~=KT.BATTLE_SLOT then
local EV="\202\194\188\254"
local b=(JY.Base[EV.."1990"] or 0)>0 and (JY.Base[EV.."1991"] or 0)==KT.BATTLE_SLOT
CC.koTownBattle=b or nil
end
return table.unpack(r,1,r.n)
end

local oldSMapEvent=SMapEvent
function SMapEvent()
if HB.defer and JY.Status==GAME_SMAP_MANUAL and HB.ev==0 then local b=HB.defer HB.defer=nil townBattleStart(b) return end-- 6.0 story (11-03)
oldSMapEvent()
if HB.startAt and avail() and HB.ev==0 then koTownVisit() return end-- (the test start above)
if avail() and HB.ev==0 then
local s=storyArrow()
local x1,y1,x2,y2=arrowRect(s[1],s[2])
if MOUSE.CLICK(x1,y1,x2,y2) then
PlayWavE(0)
koTownVisit()
end
end
end
-- (the 기능 메뉴 row "\131\123\131\095 \134\069\129\117" was dropped 10-02 at the user's request: the way in is the scene's arrow only)

-- ---- 10-13 (사용자): 기록 화면 「특산품 도감」 — every town's 특산품 상인 by chapter (the chapters not reached yet as ???), the formation
-- addon puts the tab in (koTownSpecialTab). koTownSpecialData: for its 진형 도감 (where a 병법서 is sold). An item under the mouse shows
-- its description (사용자 10-13)
function koTownSpecialData() local t=koSpecialTable() return t,KT.SPECIAL_RATE end
function koTownSpecialTab()
local CHS={"\129\1001\131\097","\129\1002\131\097","\129\1003\131\097","\129\1004\131\097"}
do local _,KS=koSpecialTable() if KS then CHS=KS end end--6.0: story phases
local function rows()
local r={}
for ci,ck in ipairs(CHS) do
local towns={}
for town,_ in pairs(koSpecialTable()[ck] or {}) do towns[#towns+1]=town end
local at={} for i,p in ipairs((DATA[ck] and DATA[ck].region and DATA[ck].region.places) or {}) do at[p[1]]=at[p[1]] or i end
table.sort(towns,function(a,b) local x,y=at[a] or 999,at[b] or 999 if x~=y then return x<y end return a<b end)-- the region map's order
for _,town in ipairs(towns) do r[#r+1]={ci=ci,ck=ck,town=town,ids=koPromotionStock(koSpecialTable()[ck][town])} end
end
return r
end
local function curChap()
local sp=koSpecialPhase() if sp then return sp end
if JY.Base==nil or JY.Status==GAME_START then return 9 end
local s=JY.Base[CHAP] or ""
for i,ck in ipairs(CHS) do if string.sub(s,1,#ck)==ck then return i end end
return 9-- (외전 · 그 밖: all shown)
end
local PER=11
local function gold(iid)
return 10*(koIsPromotionItem(iid) and koShopP(iid) or townSpecialPrice(iid))
end
-- the rows of a page and where each item's text sits: {e, y, cells={{x,w,iid,s}}}
local function layout(page,c)
local R=rows()
local now=curChap()
local out={}
for k=1,PER do
local e=R[(page-1)*PER+k]
if not e then break end
local L={e=e,y=c.oy+58+28+(k-1)*28,k=k,locked=(e.ci>now),cells={}}
if not L.locked then
local x=c.ox+176
for _,iid in ipairs(e.ids) do
local s=JY.Item[iid][I_NAME].." "..gold(iid).."\131\103"
if x+#s*8>c.ox+744 then break end
L.cells[#L.cells+1]={x=x,w=#s*8,iid=iid,s=s}
x=x+#s*8+20
end
end
out[#out+1]=L
end
return out
end
return {label="\129\120\132\091\131\066 \129\068\135\078",per=PER,
n=function() return #rows() end,
draw=function(page,c)
local y0=c.oy+58
c.txt(c.ox+24,y0,"\131\097",M_Gray) c.txt(c.ox+96,y0,"\133\088\129\083",M_Gray) c.txt(c.ox+176,y0,"\129\120\132\091\131\066 (\137\093)",M_Gray)
lib.DrawRect(c.ox+16,y0+20,c.ox+752,y0+20,RGB(112,91,57))
for _,L in ipairs(layout(page,c)) do
local y=L.y
if L.k%2==0 then lib.Background(c.ox+20,y-3,c.ox+748,y+22,190,RGB(46,35,24)) end
c.txt(c.ox+24,y,L.e.ck,M_Silver)
if L.locked then
c.txt(c.ox+96,y,"???",M_Gray) c.txt(c.ox+176,y,"\129\110\132\076 \129\094 \131\115\130\067 \136\102\129\111 \131\097\129\104\129\076\129\077",M_Gray)
else
c.txt(c.ox+96,y,L.e.town,C_Name)
for _,cl in ipairs(L.cells) do c.txt(cl.x,y,cl.s,(cl.iid>=200 and cl.iid<=211) and M_Lime or M_White) end
end
end
c.txt(c.ox+24,c.oy+418,"\131\065\129\119\129\102 \133\088\131\079\131\126\130\104 \131\105\129\117\129\065 \129\069\130\088\129\071 \131\118\133\111\129\076\129\077. \137\093\131\098 \129\068\130\119\129\067\131\080 1.5\134\099, \131\124\133\108 = \129\103\136\069 \130\126\136\070\131\087.",M_Gray)
end,
btns=function(page,c)
local out={}
for _,L in ipairs(layout(page,c)) do for _,cl in ipairs(L.cells) do out[#out+1]={x=cl.x-4,y=L.y-3,w=cl.w+8,h=24,s="",plain=true,iid=cl.iid} end end
return out
end,
tip=function(b,c)
local iid=b.iid
if not iid then return end
local it=JY.Item[iid]
local lines={{it[I_NAME].."   "..gold(iid).."\131\103",C_Name}}
for l in string.gmatch((it[I_DESC] or "").."*","([^*]*)%*") do if l~="" then lines[#lines+1]={l,M_White} end end
local w=0 for _,l in ipairs(lines) do w=math.max(w,#l[1]*8) end
w=w+24
local h=#lines*22+20
local tx=math.max(c.ox+8,math.min(b.x,c.ox+760-w))
local ty=b.y+b.h+4
if ty+h>c.oy+470 then ty=b.y-h-4 end
koRecordClassicFrame(tx,ty,w,h)
for i,l in ipairs(lines) do DrawString(tx+12,ty+10+(i-1)*22,l[1],l[2],16) end
end}
end

-- ---- 10-13 (사용자 "\133\120\130\071 \130\066\132\101\129\102\131\087 \131\115\129\067\129\083 3\130\125\129\089\130\067 \131\067\131\068 \129\094\131\077\129\111 \130\064 \133\113\130\086\129\088 \129\068\135\078 \133\124\129\071\130\067"): 기록 화면 「재도전 보상」. The limit is a chapter's
-- (free addon: koFreeExpMax result saves a story chapter, whichever battles — 사용자 10-13 "\131\097\135\105 3\130\087 \131\091\130\095\132\083"), so the page is this
-- chapter's: the count left as pips on top, then the battles the region map's 전장 · 관문 icons replay now (FIELD of this chapter):
-- 다시 싸울 수 있음 / 이야기 진행 후 / 이번 장 횟수 소진. The formation addon puts the tab in.
function koTownFreeTab()
if KT.CAMP then return HB.campTab() end-- 6.0 (11-03)
local CHS={"\129\1001\131\097","\129\1002\131\097","\129\1003\131\097","\129\1004\131\097"}
local function curChap()
if JY.Base==nil or JY.Status==GAME_START then return 0 end
local s=JY.Base[CHAP] or ""
for i,ck in ipairs(CHS) do if string.sub(s,1,#ck)==ck then return i end end
return 0
end
local function rows()
local r={}
local now=curChap()
local ck=CHS[now]
if not ck then return r end
local places={}
for place,_ in pairs(KT.FIELD[ck] or {}) do places[#places+1]=place end
local at={} for i,p in ipairs((DATA[ck] and DATA[ck].region and DATA[ck].region.places) or {}) do at[p[1]]=at[p[1]] or i end
table.sort(places,function(a,b) local x,y=at[a] or 999,at[b] or 999 if x~=y then return x<y end return a<b end)
for _,place in ipairs(places) do for _,b in ipairs(KT.FIELD[ck][place]) do r[#r+1]={place=place,b=b} end end
return r
end
local PER=9
return {label="\129\115\129\068\130\066 \131\115\129\067",per=PER,
n=function() return math.max(1,#rows()) end,
draw=function(page,c)
local fd=rawget(_G,"koFreeData")
local now=curChap()
local max=rawget(_G,"koFreeExpMax") or 3
local used=(now>0 and rawget(_G,"koFreeExpUsed")) and (rawget(_G,"koFreeExpUsed") and koFreeExpUsed()) or 0
local left=math.max(0,max-used)
if now==0 then c.ctext(c.oy+200,"\129\071\133\069\131\071 \129\103\130\093 \130\101\129\102 \133\082 \129\113 \132\079\129\075\129\076\129\077.",M_Gray) return end
-- this chapter's count: pips (● left, ○ used)
local head="\129\071\130\087 \131\097("..CHS[now]..") \129\115\129\068\130\066 \131\115\129\067"
c.txt(c.ox+24,c.oy+58,head,C_Name)
local x=c.ox+24+#head*8+16
for i=1,max do c.txt(x,c.oy+58,(i<=left) and "\161\241" or "\161\240",(i<=left) and M_Lime or M_Gray) x=x+20 end
c.txt(x+8,c.oy+58,"\133\103\131\098 "..left.."\130\087",(left>0) and M_White or M_Red)
c.txt(x+8+#("\133\103\131\098 "..left.."\130\087")*8+16,c.oy+58,"(\131\097\129\071 \131\085\129\175\129\065 \129\077\130\086 "..max.."\130\087)",M_Gray)
c.txt(c.ox+24,c.oy+82,"\130\083\134\115 \130\066\132\101\136\101 \129\087\138\080\131\087 \131\097\133\088\129\077 "..max.."\130\087, \134\064\129\123(\131\064\133\085\132\081\161\164\129\068\130\119\161\164\131\103)\129\094 \133\103\129\075\129\076\129\077.",M_Gray)
local y0=c.oy+114
c.txt(c.ox+24,y0,"\131\097\129\109",M_Gray) c.txt(c.ox+124,y0,"\130\066\132\101",M_Gray) c.txt(c.ox+520,y0,"\130\067\131\103",M_Gray)
lib.DrawRect(c.ox+16,y0+20,c.ox+752,y0+20,RGB(112,91,57))
local R=rows()
if #R==0 then c.txt(c.ox+24,y0+30,"\129\071 \131\097\129\102\130\098 \129\077\130\086 \129\088 \129\113 \132\079\130\098 \130\066\132\101\129\094 \130\097\129\075\129\076\129\077.",M_Gray) end
for k=1,PER do
local e=R[(page-1)*PER+k]
if not e then break end
local y=y0+28+(k-1)*28
if k%2==0 then lib.Background(c.ox+20,y-3,c.ox+748,y+22,190,RGB(46,35,24)) end
local d=fd and fd[e.b[1]]
c.txt(c.ox+24,y,e.place,C_Name)
c.txt(c.ox+124,y,d and d.name or "-",M_White)
local st,col
if not (d and d.map==e.b[2] and HB.fought(e.b)) then st,col="\129\071\133\069\131\071 \129\103\130\093 \133\067",M_Gray
elseif left>0 then st,col="\129\077\130\086 \137\106\133\091 \129\113 \132\079\130\077",M_Lime
else st,col="\129\071\130\087 \131\097 \197\123\129\113 \129\109\129\103",M_Red end
c.txt(c.ox+520,y,st,col)
end
c.txt(c.ox+24,c.oy+418,"\130\067\134\074 \130\067\129\068\129\102\131\087 \130\066\131\097 \161\164 \129\101\133\090 \129\110\129\071\187\095\129\083 \134\117\130\106\129\065 \130\067\130\113 \129\071\133\069\131\071 \130\066\132\101\130\104 \129\077\130\086 \129\087\129\076\129\077.",M_Gray)
end}
end

-- 6.0 (11-03): the story page: the battles of the chapters so far (this one first), where they are replayed, and whether now
function HB.campTab()
local function chapNow() if JY.Base==nil or JY.Status==GAME_START or not rawget(_G,"koFreeChapter") then return nil end return koFreeChapter() end
local function rows()
local r,fd,now={},rawget(_G,"koFreeData"),chapNow()
if not (fd and now) then return r end
for c=now,0,-1 do for _,b in ipairs(KT.CAMP) do local d=fd[b[1]] if d and d.ch==c then r[#r+1]=b end end end
return r
end
local PER=9
return {label="\129\115\129\068\130\066 \131\115\129\067",per=PER,
n=function() return math.max(1,#rows()) end,
draw=function(page,c)
local fd=rawget(_G,"koFreeData")
local now=chapNow()
if not now then c.ctext(c.oy+200,"\129\071\133\069\131\071 \129\103\130\093 \130\101\129\102 \133\082 \129\113 \132\079\129\075\129\076\129\077.",M_Gray) return end
local max=rawget(_G,"koFreeExpMax") or 3
local left=math.max(0,max-((rawget(_G,"koFreeExpUsed") and koFreeExpUsed()) or 0))
local head="\129\071\130\087 \131\097("..(now==0 and "\131\087\131\097" or ("\129\100"..now.."\131\097"))..") \129\115\129\068\130\066 \131\115\129\067"
c.txt(c.ox+24,c.oy+58,head,C_Name)
local x=c.ox+24+#head*8+16
for i=1,max do c.txt(x,c.oy+58,(i<=left) and "\161\241" or "\161\240",(i<=left) and M_Lime or M_Gray) x=x+20 end
c.txt(x+8,c.oy+58,"\133\103\131\098 "..left.."\130\087",(left>0) and M_White or M_Red)
c.txt(x+8+#("\133\103\131\098 "..left.."\130\087")*8+16,c.oy+58,"(\131\097\129\071 \131\085\129\175\129\065 \129\077\130\086 "..max.."\130\087)",M_Gray)
c.txt(c.ox+24,c.oy+82,"\130\083\134\115 \130\066\132\101\136\101 \129\087\138\080\131\087 \131\097\133\088\129\077 "..max.."\130\087, \134\064\129\123(\131\064\133\085\132\081\161\164\129\068\130\119\161\164\131\103)\129\094 \133\103\129\075\129\076\129\077.",M_Gray)
local y0=c.oy+114
c.txt(c.ox+24,y0,"\131\097\129\109",M_Gray) c.txt(c.ox+124,y0,"\130\066\132\101",M_Gray) c.txt(c.ox+520,y0,"\130\067\131\103",M_Gray)
lib.DrawRect(c.ox+16,y0+20,c.ox+752,y0+20,RGB(112,91,57))
local R=rows()
if #R==0 then c.txt(c.ox+24,y0+30,"\129\071 \131\097\129\102\130\098 \129\077\130\086 \129\088 \129\113 \132\079\130\098 \130\066\132\101\129\094 \130\097\129\075\129\076\129\077.",M_Gray) end
for k=1,PER do
local b=R[(page-1)*PER+k]
if not b then break end
local y=y0+28+(k-1)*28
if k%2==0 then lib.Background(c.ox+20,y-3,c.ox+748,y+22,190,RGB(46,35,24)) end
local d=fd and fd[b[1]]
c.txt(c.ox+24,y,b[4] or "-",C_Name)
c.txt(c.ox+124,y,d and d.name or "-",M_White)
local st,col
if not (d and d.map==b[2] and HB.fought(b)) then st,col="\129\071\133\069\131\071 \129\103\130\093 \133\067",M_Gray
elseif left>0 then st,col="\129\077\130\086 \137\106\133\091 \129\113 \132\079\130\077",M_Lime
else st,col="\129\071\130\087 \131\097 \197\123\129\113 \129\109\129\103",M_Red end
c.txt(c.ox+520,y,st,col)
end
c.txt(c.ox+24,c.oy+418,"\130\067\134\074 \130\067\129\068\129\102\131\087 \130\066\131\097 \161\164 \129\101\133\090 \129\110\129\071\187\095\129\083 \134\117\130\106\129\065 \130\067\130\113 \129\071\133\069\131\071 \130\066\132\101\130\104 \129\077\130\086 \129\087\129\076\129\077.",M_Gray)
end}
end

function koWujeNativeTownModels() return DATA end

